--[[
	Rick & Morty AI Executor — bundled build
	Generated by build.js from /src. Do not edit this file by hand.
	Paste the whole chunk into an executor and run it.

	Quick menu : press ';'   |  Dashboard: run RickMortyAI:Open()  |  Unload: RickMortyAI:Unload()
]]

--!nonstrict

local __modules, __cache = {}, {}

__modules["__root"] = function(require)
	return require
end

__modules["core/Assets"] = function(require)
--[[
	core/Assets.lua
	PNG handling from idea/png-usage.md.

	The three assets live beside the executor's workspace folder:
		title.png  — main logo (3840x2160, aspect ratio 16:9)
		rick.png   — Rick companion portrait
		morty.png  — Morty companion portrait

	Roblox cannot read arbitrary disk paths, so we hand the local file to the
	executor's `getcustomasset()` which returns a usable asset id. When that is
	unavailable (vanilla Roblox, or the file was not shipped next to the script)
	we fall back to a bundled rbxassetid so the UI still renders.
]]

local Util = require("core/Util")

local Assets = {}

-- title.png ships as a 3840x2160 canvas, but the logo art itself only fills a
-- 3468x1064 horizontal band (the rest is transparent padding). Constraining to
-- the canvas ratio would letterbox the logo into a sliver, so the constraint
-- uses the trimmed ratio instead.  See `Assets.report()` for the raw numbers.
Assets.TITLE_ASPECT = 3468 / 1064 -- ~3.259
Assets.TITLE_CANVAS = { width = 3840, height = 2160 }

Assets.files = {
	title = "title.png",
	rick = "rick.png",
	morty = "morty.png",
}

-- Searched in order, relative to the executor workspace folder.
Assets.searchPaths = { "", "imgs/", "assets/" }

-- Intentionally empty: the spec sources art from the executor workspace, and a
-- fabricated rbxassetid would silently render the wrong picture. A missing file
-- simply draws nothing, and boot raises a warning toast so the cause is obvious.
Assets.fallback = {
	title = "",
	rick = "",
	morty = "",
}

Assets.cache = {}
Assets.missing = {}

function Assets.exists(path)
	local isfile = Util.global("isfile")
	if type(isfile) ~= "function" then
		return false
	end

	local ok, result = pcall(isfile, path)
	return ok and result == true
end

--- Finds the asset on disk, trying each configured search path.
function Assets.locate(name)
	local relative = Assets.files[name] or name

	for _, prefix in ipairs(Assets.searchPaths) do
		local candidate = prefix .. relative
		if Assets.exists(candidate) then
			return candidate
		end
	end

	return nil
end

--- Resolves a logical asset name to something ImageLabel.Image accepts.
function Assets.resolve(name)
	local cached = Assets.cache[name]
	if cached ~= nil then
		return cached
	end

	local id = ""
	local located = Assets.locate(name)
	local getcustomasset = Util.global("getcustomasset")

	if located and type(getcustomasset) == "function" then
		local ok, result = pcall(getcustomasset, located)
		if ok and type(result) == "string" and result ~= "" then
			id = result
		end
	end

	if id == "" then
		id = Assets.fallback[name] or ""
		Assets.missing[name] = located ~= nil
	end

	Assets.cache[name] = id
	return id
end

function Assets.title()
	return Assets.resolve("title")
end

function Assets.portrait(companion)
	local key = string.lower(tostring(companion)) == "morty" and "morty" or "rick"
	return Assets.resolve(key)
end

--- Builds an ImageLabel pre-configured per the PNG spec.
function Assets.imageLabel(name, props, children)
	local config = {
		Name = name or "Asset",
		BackgroundTransparency = 1,
		Image = Assets.resolve(string.lower(name or "title")),
		ScaleType = Enum.ScaleType.Fit,
	}
	if props then
		for key, value in pairs(props) do
			config[key] = value
		end
	end

	-- Resolve again when the caller overrides Name after construction.
	if config.Image == "" then
		config.Image = Assets.fallback[string.lower(name or "title")] or ""
	end

	return Util.create("ImageLabel", config, children)
end

--- UIAspectRatioConstraint so the title never stretches (spec §4).
--- DominantAxis.Height keeps the requested height and derives the width, which
--- is what a wide banner wants inside a short header.
function Assets.aspect(instance, ratio, dominantAxis)
	return Util.create("UIAspectRatioConstraint", {
		AspectRatio = ratio or Assets.TITLE_ASPECT,
		AspectType = Enum.AspectType.FitWithinMaxSize,
		DominantAxis = dominantAxis or Enum.DominantAxis.Height,
		Parent = instance,
	})
end

--- Names of assets that could not be found on disk.
function Assets.missingNames()
	local missing = {}
	for _, name in ipairs({ "title", "rick", "morty" }) do
		if not Assets.locate(name) then
			table.insert(missing, name .. ".png")
		end
	end
	return missing
end

--- Human readable report for the onboarding panel / notifications.
function Assets.report()
	local lines = {}
	for _, name in ipairs({ "title", "rick", "morty" }) do
		local path = Assets.locate(name)
		table.insert(
			lines,
			string.format("%s.png: %s", name, path and ("local (" .. path .. ")") or "remote fallback")
		)
	end
	return table.concat(lines, "\n")
end

return Assets
end

__modules["core/Chat"] = function(require)
--[[
	core/Chat.lua
	Conversation pipeline: persona injection -> provider template -> transport
	-> response parsing -> history bookkeeping.

	The visible transcript only ever contains user/assistant turns; the system
	directive stays hidden (idea/backend.md §1).
]]

local CodeRunner = require("core/CodeRunner")
local Http = require("core/Http")
local Persona = require("core/Persona")
local Providers = require("core/Providers")
local State = require("core/State")
local Util = require("core/Util")

local Chat = {}

Chat.busy = false
Chat.lastError = nil

--- Builds the outbound request without sending it (used by the Code pane preview).
function Chat.compile(prompt, history)
	local providerId = State.provider()
	local provider = Providers.get(providerId)
	local packed = Persona.buildMessages(State.companion(), history or State.history, prompt)

	return {
		provider = providerId,
		url = State.data.urls[providerId] or provider.url,
		headers = Providers.buildHeaders(providerId, State.apiKey(providerId)),
		body = Providers.buildBody(providerId, {
			messages = packed.messages,
			system = packed.system,
			prompt = prompt,
			model = State.model(provider.model),
		}),
	}
end

--[[
	Sends `prompt` to the active provider.

	handlers = {
		onUser    = function(text)
		onDelta   = function(chunk)   -- received assistant text (single shot)
		onDone    = function(text)    -- parsed assistant reply
		onError   = function(message)
		onFinish  = function()        -- always runs, success or failure
	}
]]
function Chat.send(prompt, handlers)
	handlers = handlers or {}

	if Chat.busy then
		if handlers.onError then
			handlers.onError("A request is already in flight.")
		end
		return nil
	end

	if type(prompt) ~= "string" or Util.trim(prompt) == "" then
		if handlers.onError then
			handlers.onError("Prompt is empty.")
		end
		return nil
	end

	Chat.busy = true
	Chat.lastError = nil

	State.pushMessage("user", prompt)
	if handlers.onUser then
		handlers.onUser(prompt)
	end

	local handle = {
		done = false,
		cancelled = false,
		prompt = prompt,
	}

	function handle.cancel()
		handle.cancelled = true
	end

	function handle.await()
		while not handle.done do
			task.wait()
		end
	end

	task.spawn(function()
		local compiled = Chat.compile(prompt)

		local finish = function()
			Chat.busy = false
			handle.done = true
			if handlers.onFinish then
				handlers.onFinish()
			end
		end

		local fail = function(message)
			Chat.lastError = message
			if not handle.cancelled and handlers.onError then
				handlers.onError(message)
			end
			finish()
		end

		if not Http.available() then
			fail(
				"No HTTP transport available. Run inside an executor that provides "
					.. "`request`/`http_request`, or enable HTTP requests in game settings."
			)
			return
		end

		local encodedBody = Http.encode(compiled.body)
		if not encodedBody then
			fail("Could not encode the request payload.")
			return
		end

		State.bumpRequests()

		local result = Http.request({
			Url = compiled.url,
			Method = "POST",
			Headers = compiled.headers,
			Body = encodedBody,
		})

		if handle.cancelled then
			finish()
			return
		end

		if not result.ok then
			local detail = result.error or result.body or "unknown error"
			fail(string.format("%s (HTTP %s): %s", compiled.provider, tostring(result.status), tostring(detail)))
			return
		end

		local text, parseError = Providers.parse(compiled.provider, result.body)
		if not text then
			fail(parseError or "Unparseable provider response.")
			return
		end

		State.pushMessage("assistant", text)

		if handlers.onDelta then
			handlers.onDelta(text)
		end
		if handlers.onDone then
			handlers.onDone(text)
		end

		finish()
	end)

	return handle
end

--[[
	Convenience for the semicolon quick menu and the Code pane:
	send a prompt, execute any returned Lua, report through `log`.
]]
function Chat.sendAndRun(prompt, log, handlers)
	handlers = handlers or {}
	local logger = log or function() end

	return Chat.send(prompt, {
		onUser = function(text)
			logger("> " .. text, "user")
			if handlers.onUser then
				handlers.onUser(text)
			end
		end,
		onDone = function(text)
			if handlers.onReply then
				handlers.onReply(text)
			end

			if CodeRunner.looksLikeCode(text) then
				local ok, output = CodeRunner.execute(text)
				if ok then
					logger(output ~= "" and ("[executed] " .. output) or "[executed] script finished", "ok")
				else
					logger("[execution error] " .. tostring(output), "error")
				end
				if handlers.onExecuted then
					handlers.onExecuted(ok, output)
				end
			else
				logger("[no executable block] reply shown in chat only", "warn")
			end
		end,
		onError = function(message)
			logger("[error] " .. tostring(message), "error")
			if handlers.onError then
				handlers.onError(message)
			end
		end,
		onFinish = handlers.onFinish,
	})
end

return Chat
end

__modules["core/CodeRunner"] = function(require)
--[[
	core/CodeRunner.lua
	Code extraction + execution from idea/backend.md §4.

	The hot path is:
	  1. isolate the raw ```lua block out of the model's prose
	  2. publish it into a script container inside Workspace
	  3. run it against the executor's global environment
]]

local Util = require("core/Util")

local CodeRunner = {}

CodeRunner.CONTAINER_NAME = "RickMortyAI_Scripts"

--- Every fenced block in the message, as { language, code }.
function CodeRunner.extractBlocks(text)
	local blocks = {}

	for language, body in string.gmatch(tostring(text or ""), "```([%w_%+%-]*)\r?\n(.-)```") do
		table.insert(blocks, {
			language = language == "" and "lua" or language,
			code = body,
		})
	end

	return blocks
end

--- Code that should actually be executed: prefer lua/luau blocks.
function CodeRunner.extractCode(text)
	local blocks = CodeRunner.extractBlocks(text)
	local preferred = {}

	for _, block in ipairs(blocks) do
		local language = string.lower(block.language)
		if language == "lua" or language == "luau" or language == "" then
			table.insert(preferred, block.code)
		end
	end

	if #preferred > 0 then
		return table.concat(preferred, "\n\n"), #preferred
	end

	if #blocks > 0 then
		local all = {}
		for _, block in ipairs(blocks) do
			table.insert(all, block.code)
		end
		return table.concat(all, "\n\n"), #blocks
	end

	return nil, 0
end

--- Removes every fence so the Code pane shows clean Luau.
function CodeRunner.stripFences(text)
	local stripped = tostring(text or ""):gsub("```[%w_%+%-]*\r?\n", ""):gsub("```", "")
	return Util.trim(stripped)
end

--- True when the text looks executable rather than conversational.
function CodeRunner.looksLikeCode(text)
	local source = tostring(text or "")
	if source:find("```") then
		return true
	end

	local signatures = {
		"local ",
		"function ",
		"game:GetService",
		"game%.GetService",
		"Instance%.new",
		"task%.wait",
		"print%(",
		"end",
	}

	local hits = 0
	for _, pattern in ipairs(signatures) do
		if source:find(pattern) then
			hits += 1
		end
	end

	return hits >= 2
end

--- Writes the generated source into Workspace as a script container (spec §4).
function CodeRunner.publish(source, name)
	local container = Util.find(workspace, CodeRunner.CONTAINER_NAME)
	if not container then
		container = Util.create("Folder", {
			Name = CodeRunner.CONTAINER_NAME,
			Parent = workspace,
		})
	end

	local holder = Instance.new("ModuleScript")
	holder.Name = name or ("generated_" .. tostring(os.time()))

	local ok = pcall(function()
		holder.Source = source
	end)

	if not ok then
		-- Some executors lock Source outside of elevated identity.
		holder:SetAttribute("Source", source)
	end

	holder.Parent = container
	return holder
end

--- Compiles and runs source with access to the executor globals.
function CodeRunner.run(source, options)
	options = options or {}

	local loader = Util.global("loadstring") or loadstring
	if type(loader) ~= "function" then
		return false, "loadstring is unavailable in this environment."
	end

	local chunk, compileError = loader(source, options.chunkName or "RickMortyAI")
	if not chunk then
		return false, tostring(compileError)
	end

	local setfenv = Util.global("setfenv")
	if type(setfenv) == "function" then
		pcall(setfenv, chunk, Util.environment())
	end

	if options.defer then
		task.spawn(function()
			local ok, result = pcall(chunk)
			if options.onError and not ok then
				options.onError(tostring(result))
			end
		end)
		return true, nil
	end

	local ok, result = pcall(chunk)
	if not ok then
		return false, tostring(result)
	end

	return true, result
end

--- Extract -> publish -> run. Returns (ok, output).
function CodeRunner.execute(text, options)
	options = options or {}

	local source = CodeRunner.extractCode(text)
	if not source or Util.trim(source) == "" then
		return false, "No executable code block found in the response."
	end

	local published, holder = pcall(CodeRunner.publish, source, options.name)
	local ok, output = CodeRunner.run(source, options)

	if not ok then
		return false, tostring(output)
	end

	local note = published and "" or "\n(publishing to Workspace failed)"
	return true, tostring(output) .. note, holder
end

return CodeRunner
end

__modules["core/Cowork"] = function(require)
--[[
	core/Cowork.lua
	Cowork mode filesystem bridge from idea/backend.md §2.

	Sequence:
	  1. create/verify the /rick_morty_bridge/ folder in the executor workspace
	  2. write server.js + index.html (the external high-fidelity interface)
	  3. write launch_bridge.bat (Windows) / launch_bridge.sh (Mac/Linux)
	  4. write config.json so the bridge knows the active provider/keys
	  5. hand the user a notification pointing at the launcher

	The bridge serves http://localhost:7896 and talks to the configured
	provider directly from Node, so no Roblox HTTP restrictions apply.
]]

local Http = require("core/Http")
local Providers = require("core/Providers")
local State = require("core/State")
local Util = require("core/Util")

local Cowork = {}

Cowork.DIR = "rick_morty_bridge"
Cowork.PORT = 7896
Cowork.URL = "http://localhost:7896"

Cowork.launchers = {
	windows = "launch_bridge.bat",
	posix = "launch_bridge.sh",
}

--- Raw text assets inlined by build.js from /bridge.
function Cowork.assets()
	local ok, assets = pcall(require, "bundle/assets")
	if ok and type(assets) == "table" then
		return assets
	end

	return {}
end

function Cowork.available()
	return type(Util.global("writefile")) == "function"
end

function Cowork.path(relative)
	return Cowork.DIR .. "/" .. relative
end

function Cowork.ensureFolder()
	local isfolder = Util.global("isfolder")
	local makefolder = Util.global("makefolder")

	if type(isfolder) == "function" then
		local ok, exists = pcall(isfolder, Cowork.DIR)
		if ok and exists then
			return true
		end
	end

	if type(makefolder) == "function" then
		pcall(makefolder, Cowork.DIR)
		return true
	end

	return false
end

function Cowork.write(relative, contents)
	local writefile = Util.global("writefile")
	if type(writefile) ~= "function" then
		return false, "writefile is unavailable in this environment."
	end

	local path = Cowork.path(relative)
	local ok, err = pcall(writefile, path, contents)
	if not ok then
		return false, tostring(err)
	end

	return true, path
end

--- Provider wiring for the Node bridge, mirroring the Lua provider matrix.
function Cowork.config()
	local providerId = State.provider()
	local provider = Providers.get(providerId)

	return Http.encode({
		provider = providerId,
		style = provider.style,
		model = State.model(provider.model),
		url = State.data.urls[providerId] or provider.url,
		apiKey = State.apiKey(providerId),
		companion = State.companion(),
		persona = require("core/Persona").systemMessage(State.companion()),
		port = Cowork.PORT,
	})
end

--- Writes the whole bridge. Returns (ok, filesWrittenOrError).
function Cowork.build()
	if not Cowork.available() then
		return false, "This executor does not expose writefile(), so the Cowork bridge cannot be generated."
	end

	Cowork.ensureFolder()

	local assets = Cowork.assets()
	local written = {}
	local failures = {}

	local payload = {
		{ Cowork.launchers.windows, assets["bridge/launch_bridge.bat"] },
		{ Cowork.launchers.posix, assets["bridge/launch_bridge.sh"] },
		{ "server.js", assets["bridge/server.js"] },
		{ "index.html", assets["bridge/index.html"] },
		{ "README.txt", assets["bridge/README.txt"] },
		{ "config.json", Cowork.config() },
	}

	for _, entry in ipairs(payload) do
		local name, contents = entry[1], entry[2]

		if type(contents) == "string" and contents ~= "" then
			local ok, pathOrError = Cowork.write(name, contents)
			if ok then
				table.insert(written, pathOrError)
			else
				table.insert(failures, name .. ": " .. tostring(pathOrError))
			end
		else
			table.insert(failures, name .. ": missing bundled asset")
		end
	end

	-- Best effort: make the shell launcher executable on POSIX hosts.
	local run = Util.global("run") or Util.global("shell")
	if type(run) == "function" then
		pcall(run, string.format('chmod +x "%s"', Cowork.path(Cowork.launchers.posix)))
	end

	if #written == 0 then
		return false, table.concat(failures, "\n")
	end

	return true, written
end

--- Human-readable instructions for the notification panel.
function Cowork.instructions()
	local lines = {
		"1. Open your executor's workspace folder.",
		"2. Enter the " .. Cowork.DIR .. " directory.",
		"3. Double-click " .. Cowork.launchers.windows .. " (Windows) or run " .. Cowork.launchers.posix .. ".",
		"4. The dashboard opens at " .. Cowork.URL .. ".",
		"Node.js 18+ must be installed for the bridge to start.",
	}

	return table.concat(lines, "\n")
end

function Cowork.status()
	if not Cowork.available() then
		return "unavailable (no writefile)"
	end

	local isfolder = Util.global("isfolder")
	if type(isfolder) == "function" then
		local ok, exists = pcall(isfolder, Cowork.DIR)
		if ok and exists then
			return "ready in " .. Cowork.DIR
		end
	end

	return "not generated"
end

return Cowork
end

__modules["core/Fonts"] = function(require)
--[[
	core/Fonts.lua
	Typography hierarchy from idea/fonts.md.

	| Role              | Enum.Font              | Size |
	| ----------------- | ---------------------- | ---- |
	| Headers / titles  | LuckiestGuy            | 32   |
	| Subheadings       | GothamBold             | 18   |
	| Buttons           | GothamBold             | 16   |
	| Body / dialogue   | Gotham                 | 14   |
	| Code / terminal   | RobotoMono             | 12   |
]]

local Util = require("core/Util")

local Fonts = {}

Fonts.family = {
	title = Enum.Font.LuckiestGuy,
	button = Enum.Font.GothamBold,
	body = Enum.Font.Gotham,
	code = Enum.Font.RobotoMono,
}

-- name -> { Font, TextSize, align, wrapped }
Fonts.roles = {
	title = {
		Font = Enum.Font.LuckiestGuy,
		TextSize = 32,
		align = Enum.TextXAlignment.Center,
		yAlign = Enum.TextYAlignment.Center,
	},
	subtitle = {
		Font = Enum.Font.GothamBold,
		TextSize = 18,
		align = Enum.TextXAlignment.Left,
	},
	button = {
		Font = Enum.Font.GothamBold,
		TextSize = 16,
		align = Enum.TextXAlignment.Center,
		yAlign = Enum.TextYAlignment.Center,
	},
	body = {
		Font = Enum.Font.Gotham,
		TextSize = 14,
		align = Enum.TextXAlignment.Left,
		wrapped = true,
	},
	small = {
		Font = Enum.Font.Gotham,
		TextSize = 12,
		align = Enum.TextXAlignment.Left,
		wrapped = true,
	},
	code = {
		Font = Enum.Font.RobotoMono,
		TextSize = 12,
		align = Enum.TextXAlignment.Left,
		wrapped = false,
	},
	log = {
		Font = Enum.Font.RobotoMono,
		TextSize = 11,
		align = Enum.TextXAlignment.Left,
		wrapped = true,
	},
}

--- Applies a role (plus optional overrides) to any text-bearing instance.
function Fonts.apply(instance, role, overrides)
	local spec = Fonts.roles[role or "body"] or Fonts.roles.body

	instance.Font = spec.Font
	instance.TextSize = spec.TextSize
	instance.TextXAlignment = spec.align or Enum.TextXAlignment.Left
	instance.TextYAlignment = spec.yAlign or Enum.TextYAlignment.Top
	instance.TextWrapped = spec.wrapped or false

	if overrides then
		for key, value in pairs(overrides) do
			instance[key] = value
		end
	end

	return instance
end

--- TextLabel/TextButton/TextBox factory with typography applied.
--- Explicit props win over the role defaults; Parent is applied last.
function Fonts.new(className, role, props)
	local config = {}
	local parent

	if props then
		for key, value in pairs(props) do
			if key == "Parent" then
				parent = value
			else
				config[key] = value
			end
		end
	end

	local instance = Util.create(className or "TextLabel", config)
	Fonts.apply(instance, role)

	for key, value in pairs(config) do
		instance[key] = value
	end

	if parent then
		instance.Parent = parent
	end

	return instance
end

--- Auto-sizing label used by the chat transcript and log panes.
function Fonts.autoSized(role, overrides)
	local config = {}

	if overrides then
		for key, value in pairs(overrides) do
			config[key] = value
		end
	end

	config.AutomaticSize = config.AutomaticSize or Enum.AutomaticSize.Y
	config.TextWrapped = true
	config.Size = config.Size or UDim2.new(1, 0, 0, 0)
	if config.BackgroundTransparency == nil then
		config.BackgroundTransparency = 1
	end

	return Fonts.new("TextLabel", role or "body", config)
end

return Fonts
end

__modules["core/Http"] = function(require)
--[[
	core/Http.lua
	Network transport from idea/backend.md §3.

	Roblox's HttpService refuses most third-party domains, so we prefer the
	executor's privileged request function (`request`, `http_request`,
	`syn.request`, ...) and only fall back to `HttpService:RequestAsync`.

	Every call returns a normalised result table so callers never branch on
	which transport actually ran:

		{ ok = boolean, status = number, body = string, error = string? }
]]

local HttpService = game:GetService("HttpService")

local Util = require("core/Util")

local Http = {}

Http.TIMEOUT = 60

--- Picks whichever privileged requester this executor exposes.
local function requester()
	local env = Util.environment()

	local candidates = {
		env.request,
		env.http_request,
		env.syn and env.syn.request,
		env.http and env.http.request,
		env.krnl and env.krnl.request,
		env.fluxus and env.fluxus.request,
		env.electron and env.electron.request,
		env.volt and env.volt.request,
	}

	for _, candidate in ipairs(candidates) do
		if type(candidate) == "function" then
			return candidate
		end
	end

	for _, name in ipairs({ "request", "http_request" }) do
		local fn = Util.global(name)
		if type(fn) == "function" then
			return fn
		end
	end

	return nil
end

function Http.encode(value)
	local ok, encoded = pcall(function()
		return HttpService:JSONEncode(value)
	end)

	if not ok then
		return nil, tostring(encoded)
	end

	return encoded
end

function Http.decode(text)
	if type(text) ~= "string" or Util.trim(text) == "" then
		return nil
	end

	local ok, decoded = pcall(function()
		return HttpService:JSONDecode(text)
	end)

	if not ok then
		return nil
	end

	return decoded
end

function Http.encodeQuery(params)
	local parts = {}
	for key, value in pairs(params or {}) do
		table.insert(parts, string.format("%s=%s", key, tostring(value)))
	end
	return table.concat(parts, "&")
end

--- Perform a request. `options` = { Url, Method, Headers, Body }.
function Http.request(options)
	local url = options.Url or options.url
	local method = options.Method or options.method or "GET"
	local headers = options.Headers or options.headers or {}
	local body = options.Body or options.body

	if body == nil and options.json ~= nil then
		body = Http.encode(options.json)
	end

	if type(body) == "table" then
		body = Http.encode(body)
	end

	local fn = requester()
	if fn then
		local ok, response = pcall(fn, {
			Url = url,
			Method = method,
			Headers = headers,
			Body = body,
		})

		if ok and type(response) == "table" then
			local status = response.StatusCode or response.Status or 0
			return {
				ok = status >= 200 and status < 300,
				status = status,
				body = response.Body or response.body or "",
				error = nil,
			}
		end

		if not ok then
			return { ok = false, status = 0, body = "", error = tostring(response) }
		end
	end

	-- Fallback: only works for domains whitelisted in game settings.
	local ok, response = pcall(function()
		return HttpService:RequestAsync({
			Url = url,
			Method = method,
			Headers = headers,
			Body = body,
		})
	end)

	if ok and type(response) == "table" then
		return {
			ok = response.Success == true,
			status = response.StatusCode or 0,
			body = response.Body or "",
			error = response.Success and nil or response.StatusMessage,
		}
	end

	return {
		ok = false,
		status = 0,
		body = "",
		error = "No privileged HTTP transport available ("
			.. tostring(response)
			.. "). Enable HTTP requests or run inside an executor.",
	}
end

--- True when the executor exposes a usable privileged transport.
function Http.available()
	return requester() ~= nil
end

function Http.transportName()
	local fn = requester()
	if not fn then
		return "HttpService (whitelisted domains only)"
	end

	local env = Util.environment()
	if env.request == fn then
		return "request"
	end
	if env.http_request == fn then
		return "http_request"
	end
	if env.syn and env.syn.request == fn then
		return "syn.request"
	end

	return "privileged request"
end

return Http
end

__modules["core/Palette"] = function(require)
--[[
	core/Palette.lua
	Every colour constant from idea/colour-palette.md.

	Three layers, matching the spec:
	  1. surfaces  — Citadel space station panels (#0D1117 / #161B22 / #21262D / #30363D)
	  2. neon      — Portal Green / Dimension Pink / Plasma Link Cyan
	  3. characters — Rick and Morty theme overlays
	Plus the two interactive state sequences (portal green, dark console).
