		accent = Util.hex("#FFE600"), -- t-shirt yellow
		text = Util.hex("#FFAA00"), -- alert amber
		glow = Util.hex("#FF5500"), -- panic orange
		portrait = "morty",
	},
}

Palette.characterOrder = { "Rick", "Morty" }

-- 4. Interactive state variations ---------------------------------------------

Palette.states = {
