__modules["core/Persona"] = function(require)
--[[
	core/Persona.lua
	Persona prompt injection engine from idea/backend.md §1.

	Every fresh conversation chain gets a system-level directive prepended and
	the raw text is never shown in the visible chat log (the UI only renders
	`role == "user"` / `role == "assistant"` entries).

	`Persona.PreparePayload` is the reference implementation straight from the
	spec (system message on a fresh chain only).
	`Persona.buildMessages` is the transport variant the chat pipeline uses,
	which keeps the persona attached to every stateless HTTP call.
]]

local HttpService = game:GetService("HttpService")

local Persona = {}

Persona.prompts = {
	Rick = "Act like Rick from the famous show 'Rick and Morty' when explaining, debugging, writing or editing code. Be cynical, highly intelligent, slightly erratic, use his iconic speech patterns, and dismissive yet helpful.",
	Morty = "Act like Morty from the famous show 'Rick and Morty' when explaining, debugging, writing or editing code. Be anxious, stutter slightly, hesitant, but trying your absolute best to help out.",
}

--- Short form used by the quick menu overlay (ui-creation.md §4).
Persona.short = {
	Rick = "Act like Rick from the famous show Rick and Morty when explaining, debugging, writing or editing code.",
	Morty = "Act like Morty from the famous show Rick and Morty when explaining, debugging, writing or editing code.",
}

--- House rules that stop the model from burying code in prose.
Persona.rules = table.concat({
	"Always answer in Luau (Roblox Lua).",
	"Put every executable block in a fenced ```lua code block.",
	"Keep commentary short and in character.",
}, " ")

function Persona.prompt(choice)
	return Persona.prompts[choice] or Persona.prompts.Rick
end

function Persona.shortPrompt(choice)
	return Persona.short[choice] or Persona.short.Rick
end

function Persona.systemMessage(choice)
	return Persona.prompt(choice) .. " " .. Persona.rules
end

-- Spec implementation (idea/backend.md §1) ------------------------------------

function Persona.PreparePayload(userChoice, userPrompt, providerTemplate, chatHistory)
	local systemMessage = Persona.prompts[userChoice]
	local fullMessages = {}

	-- Inject system persona rule at the start of a fresh chain
	if #chatHistory == 0 then
		table.insert(fullMessages, { role = "system", content = systemMessage })
	end

	-- Append historical logs
	for _, msg in ipairs(chatHistory) do
		table.insert(fullMessages, msg)
	end

	-- Append the immediate active prompt
	table.insert(fullMessages, { role = "user", content = userPrompt })

	-- Merge into the structural API template
	local finalPayload = HttpService:JSONDecode(providerTemplate)
	finalPayload.messages = fullMessages

	return HttpService:JSONEncode(finalPayload)
end

-- Transport variant ----------------------------------------------------------

--- Returns { system = string, messages = { { role, content }, ... } }.
--- The system directive is guaranteed present regardless of history length.
function Persona.buildMessages(userChoice, history, userPrompt)
	local messages = {}
	local hasSystem = false

	for _, message in ipairs(history or {}) do
		if message.role == "system" then
			hasSystem = true
		end
		table.insert(messages, { role = message.role, content = message.content })
	end

	if userPrompt and userPrompt ~= "" then
		table.insert(messages, { role = "user", content = userPrompt })
	end

	return {
		system = Persona.systemMessage(userChoice),
		messages = messages,
		hasSystem = hasSystem,
	}
end

--- Strips persona/system entries before writing to the visible transcript.
function Persona.visibleHistory(history)
	local visible = {}
	for _, message in ipairs(history or {}) do
		if message.role ~= "system" then
			table.insert(visible, message)
		end
	end
	return visible
end

return Persona
end

__modules["core/Providers"] = function(require)
--[[
	core/Providers.lua
	The API matrix from idea/ui-creation.md §2 and idea/main.md §5.

	Each provider ships with the preset request template from the spec, a
	payload "style" describing how to merge messages into that template, and a
	response style describing how to pull the assistant text back out.

	  OpenRouter  — multi-model balancing          (openai style)
	  AgentRouter — automated multi-step loops     (agent style)
	  Anthropic   — architectural Luau projects    (anthropic style)
	  OpenAI      — rapid syntax responses         (openai style)
	  DeepSeek    — high-speed algorithmic parsing (openai style)
	  FreeBuff    — localised open-access route    (freebuff style)
]]

local Http = require("core/Http")
local Util = require("core/Util")

local Providers = {}

Providers.order = { "OpenRouter", "AgentRouter", "Anthropic", "OpenAI", "DeepSeek", "FreeBuff" }

Providers.list = {
	OpenRouter = {
		id = "OpenRouter",
		url = "https://openrouter.ai/api/v1/chat/completions",
		style = "openai",
		model = "anthropic/claude-3.5-sonnet",
		template = '{"model": "anthropic/claude-3.5-sonnet", "messages": []}',
		description = "Flexible multi-model balancing across hundreds of endpoints.",
		keyLabel = "OpenRouter API key",
		headers = { ["Content-Type"] = "application/json" },
	},

	AgentRouter = {
		id = "AgentRouter",
		url = "http://localhost:7896/api/agent",
		style = "agent",
		model = "default",
		template = '{"agent": "default", "prompt": ""}',
		description = "Structural automated multi-step development loops.",
		keyLabel = "Gateway token (optional)",
		headers = { ["Content-Type"] = "application/json" },
	},

	Anthropic = {
		id = "Anthropic",
		url = "https://api.anthropic.com/v1/messages",
		style = "anthropic",
		model = "claude-3-5-sonnet-20241022",
		template = '{"model": "claude-3-5-sonnet-20241022", "max_tokens": 1024}',
		description = "Seeded for complex architectural Luau projects.",
		keyLabel = "Anthropic API key",
		maxTokens = 4096,
		headers = {
			["Content-Type"] = "application/json",
			["anthropic-version"] = "2023-06-01",
		},
	},

	OpenAI = {
		id = "OpenAI",
		url = "https://api.openai.com/v1/chat/completions",
		style = "openai",
		model = "gpt-4o",
		template = '{"model": "gpt-4o", "messages": []}',
		description = "Rapid syntax responses and variable corrections.",
		keyLabel = "OpenAI API key",
		headers = { ["Content-Type"] = "application/json" },
	},

	DeepSeek = {
		id = "DeepSeek",
		url = "https://api.deepseek.com/chat/completions",
		style = "openai",
		model = "deepseek-chat",
		template = '{"model": "deepseek-chat", "messages": []}',
		description = "High-speed algorithmic parsing routines.",
		keyLabel = "DeepSeek API key",
		headers = { ["Content-Type"] = "application/json" },
	},

	FreeBuff = {
		id = "FreeBuff",
		url = "http://localhost:7896/api/freebuff",
		style = "freebuff",
		model = "freebuff",
		template = '{"provider": "freebuff", "input": ""}',
		description = "Immediate localised open-access development path.",
		keyLabel = "Not required",
		headers = { ["Content-Type"] = "application/json" },
	},
}

-- Keys searched (in order) when a response shape is unknown.
local PRIORITY_KEYS = {
	"content",
	"text",
	"output",
	"response",
	"completion",
	"result",
	"answer",
	"message",
}

function Providers.get(id)
	return Providers.list[id] or Providers.list.OpenRouter
end

function Providers.ids()
	return Providers.order
end

function Providers.template(id)
	return Providers.get(id).template
end

--- Decoded preset template, safe to mutate.
function Providers.baseBody(id)
	local decoded = Http.decode(Providers.template(id))
	if type(decoded) ~= "table" then
		return { messages = {} }
	end

	return decoded
end

--- Merges the conversation into the provider's preset template.
--- `request` = { messages = {...}, system = string, prompt = string, model = string }
function Providers.buildBody(id, request)
	local provider = Providers.get(id)
	local body = Providers.baseBody(id)
	local model = request.model or provider.model
	local messages = request.messages or {}

	if provider.style == "openai" then
		body.model = model
		body.messages = messages
	elseif provider.style == "anthropic" then
		body.model = model
		body.max_tokens = body.max_tokens or provider.maxTokens or 4096
		body.system = request.system

		local filtered = {}
		for _, message in ipairs(messages) do
			if message.role ~= "system" then
				table.insert(filtered, { role = message.role, content = message.content })
			end
		end
		if #filtered == 0 and request.prompt then
			table.insert(filtered, { role = "user", content = request.prompt })
		end
		body.messages = filtered
	elseif provider.style == "agent" then
		body.agent = body.agent or "default"
		body.prompt = request.prompt or ""
		body.messages = messages
		body.system = request.system
	else
		body.provider = body.provider or "freebuff"
		body.input = request.prompt or ""
		body.messages = messages
		body.system = request.system
	end

	return body
end

--- Auth headers per backend.md §3 (bearer token + content type).
function Providers.buildHeaders(id, key)
	local provider = Providers.get(id)
	local headers = {}

	for name, value in pairs(provider.headers or {}) do
		headers[name] = value
	end

	headers["Content-Type"] = "application/json"

	if type(key) == "string" and key ~= "" then
		headers["Authorization"] = "Bearer " .. key
		if id == "Anthropic" then
			headers["x-api-key"] = key
		end
	end

	if id == "OpenRouter" then
		headers["HTTP-Referer"] = "https://local.rick-morty-ai-executor"
		headers["X-Title"] = "Rick & Morty AI Executor"
	end

	return headers
end

function Providers.endpoint(id)
	local provider = Providers.get(id)
	return provider.url
end

function Providers.label(id)
	local provider = Providers.get(id)
	return string.format("%s - %s", provider.id, provider.description)
end

local function deepFindString(value, depth)
	if depth > 6 or value == nil then
		return nil
	end

	if type(value) == "string" then
		return value
	end

	if type(value) ~= "table" then
		return nil
	end

	for _, key in ipairs(PRIORITY_KEYS) do
		local candidate = value[key]
		if type(candidate) == "string" and Util.trim(candidate) ~= "" then
			return candidate
		end
		if type(candidate) == "table" then
			local nested = deepFindString(candidate, depth + 1)
			if nested then
				return nested
			end
		end
	end

	if #value > 0 then
		return deepFindString(value[1], depth + 1)
	end

	return nil
end

function Providers.describeError(err)
	if type(err) == "string" then
		return err
	end

	if type(err) == "table" then
		if type(err.message) == "string" then
			return err.message
		end

		local encoded = Http.encode(err)
		if encoded then
			return encoded
		end
	end

	return tostring(err)
end

--- Extracts the assistant text from a raw response body.
function Providers.parse(id, body)
	local provider = Providers.get(id)

	if type(body) ~= "string" or Util.trim(body) == "" then
		return nil, "The provider returned an empty response."
	end

	local decoded = Http.decode(body)
	if type(decoded) ~= "table" then
		-- Some gateways answer with plain text.
		return Util.trim(body), nil
	end

	if decoded.error then
		return nil, Providers.describeError(decoded.error)
	end

	local text

	if provider.style == "openai" then
		local choice = decoded.choices and decoded.choices[1]
		if choice then
			text = (choice.message and choice.message.content) or choice.text
		end
	elseif provider.style == "anthropic" then
		if type(decoded.content) == "table" then
			for _, part in ipairs(decoded.content) do
				if part.type == "text" and type(part.text) == "string" then
					text = text and (text .. part.text) or part.text
				end
			end
		end
		text = text or decoded.completion
	else
		text = decoded.output or decoded.text or decoded.response or decoded.result
	end

	text = text or deepFindString(decoded, 0)

	if type(text) ~= "string" or Util.trim(text) == "" then
		return nil, "Could not locate assistant text in the provider response."
	end

	return text, nil
end

return Providers
end

__modules["core/State"] = function(require)
--[[
	core/State.lua
	Runtime configuration + conversation state.

	Persisted to `rick_morty_ai_config.json` in the executor workspace via the
	privileged `writefile`/`readfile` pair, so the chosen companion, provider,
	API keys and onboarding flag survive between sessions.
	See idea/backend.md §1 (persona) and idea/ui-creation.md §2 (providers).
]]

local HttpService = game:GetService("HttpService")

local Util = require("core/Util")

local State = {}

State.CONFIG_PATH = "rick_morty_ai_config.json"
State.SCHEMA_VERSION = 1

State.data = {
	version = State.SCHEMA_VERSION,
	companion = nil, -- "Rick" | "Morty"
	provider = "OpenRouter",
	keys = {}, -- provider id -> bearer token
	models = {}, -- provider id -> model override
	urls = {}, -- provider id -> endpoint override
	onboarded = false,
	sessions = {}, -- archived conversations for the sidebar
	stats = { requests = 0, tokens = 0 },
}

--- Active conversation, always an array of { role, content }.
State.history = {}

State.listeners = {}

-- Persistence -----------------------------------------------------------------

function State.load()
	local readfile = Util.global("readfile")
	if type(readfile) ~= "function" then
		return State.data
	end

	local ok, raw = pcall(readfile, State.CONFIG_PATH)
	if not ok or type(raw) ~= "string" or Util.trim(raw) == "" then
		return State.data
	end

	local decodedOk, decoded = pcall(function()
		return HttpService:JSONDecode(raw)
	end)
	if not decodedOk or type(decoded) ~= "table" then
		return State.data
	end

	for key, value in pairs(decoded) do
		if State.data[key] ~= nil or key == "companion" then
			State.data[key] = value
		end
	end

	if type(State.data.keys) ~= "table" then
		State.data.keys = {}
	end
	if type(State.data.models) ~= "table" then
		State.data.models = {}
	end
	if type(State.data.sessions) ~= "table" then
		State.data.sessions = {}
	end

	return State.data
end

function State.save()
	local writefile = Util.global("writefile")
	if type(writefile) ~= "function" then
		return false
	end

	local encodedOk, encoded = pcall(function()
		return HttpService:JSONEncode(State.data)
	end)
	if not encodedOk then
		return false
	end

	local ok = pcall(writefile, State.CONFIG_PATH, encoded)
	return ok
end

-- Observers -------------------------------------------------------------------

function State.onChange(callback)
	table.insert(State.listeners, callback)
	return function()
		local index = table.find(State.listeners, callback)
		if index then
			table.remove(State.listeners, index)
		end
	end
end

function State.notify(key, value)
	for _, listener in ipairs(State.listeners) do
		pcall(listener, key, value, State.data)
	end
end

-- Accessors -------------------------------------------------------------------

function State.companion()
	return State.data.companion or "Rick"
end

function State.setCompanion(name)
	State.data.companion = (string.lower(tostring(name)) == "morty") and "Morty" or "Rick"
	State.save()
	State.notify("companion", State.data.companion)
	return State.data.companion
end

function State.provider()
	return State.data.provider or "OpenRouter"
end

function State.setProvider(id)
	State.data.provider = id
	State.save()
	State.notify("provider", id)
	return id
end

function State.apiKey(id)
	return State.data.keys[id or State.provider()] or ""
end

function State.setApiKey(value, id)
	State.data.keys[id or State.provider()] = value
	State.save()
	State.notify("key", value)
	return value
end

function State.model(fallback)
	local id = State.provider()
	return State.data.models[id] or fallback
end

function State.setModel(value)
	State.data.models[State.provider()] = value
	State.save()
	State.notify("model", value)
	return value
end

function State.bumpRequests()
	State.data.stats.requests = (State.data.stats.requests or 0) + 1
	State.save()
end

-- Conversation ----------------------------------------------------------------

function State.pushMessage(role, content)
	table.insert(State.history, { role = role, content = content })
	State.notify("history", #State.history)
	return #State.history
end

function State.setHistory(history)
	State.history = history or {}
	State.notify("history", #State.history)
end

function State.resetHistory()
	if #State.history > 0 then
		State.archive()
	end
	State.history = {}
	State.notify("history", 0)
end

--- Snapshot the active conversation into the sidebar's session list.
function State.archive()
	if #State.history == 0 then
		return nil
	end

	local firstUser
	for _, message in ipairs(State.history) do
		if message.role == "user" then
			firstUser = message.content
			break
		end
	end

	local session = {
		title = Util.truncate(firstUser or "Untitled conversation", 42),
		count = #State.history,
		time = Util.timestamp(),
		messages = State.history,
	}

	table.insert(State.data.sessions, 1, session)
	while #State.data.sessions > 20 do
		table.remove(State.data.sessions)
	end

	State.save()
	State.notify("sessions", State.data.sessions)
	return session
end

return State
end

__modules["core/Typewriter"] = function(require)
--[[
	core/Typewriter.lua
	Letter-by-letter rendering from idea/fonts.md §3 and idea/main.md §4.

	  * 0.03s hard delay between characters
	  * clicking the active dialogue frame reveals the whole block instantly
	  * RichText stays enabled so inline styling survives the reveal loop
	  * one click sound per rendered glyph — rbxassetid://9114223164,
	    volume 0.3, playback speed 1.2
]]

local SoundService = game:GetService("SoundService")

local Fonts = require("core/Fonts")
local Util = require("core/Util")

local Typewriter = {}

Typewriter.SPEED = 0.03
Typewriter.SOUND_ID = "rbxassetid://9114223164"
Typewriter.SOUND_VOLUME = 0.3
Typewriter.SOUND_PITCH = 1.2

local clickSound

local function sound()
	if clickSound and clickSound.Parent then
		return clickSound
	end

	clickSound = Util.create("Sound", {
		Name = "RickMortyTypewriterClick",
		SoundId = Typewriter.SOUND_ID,
		Volume = Typewriter.SOUND_VOLUME,
		PlaybackSpeed = Typewriter.SOUND_PITCH,
		Parent = SoundService,
	})

	return clickSound
end

--- Minimal markdown -> RichText for the dialogue panes.
function Typewriter.toRichText(markdown)
	local text = tostring(markdown or "")

	-- Escape first so stray angle brackets cannot become tags.
	text = text:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")

	-- Fenced blocks collapsed to a single styled line.
	text = text:gsub("```[%w_%+%-]*\r?\n(.-)```", function(code)
		return '<font face="RobotoMono">' .. code:gsub("%s+$", "") .. "</font>"
	end)

	-- Inline code.
	text = text:gsub("`([^`\n]+)`", '<font face="RobotoMono">%1</font>')

	-- Bold / italic.
	text = text:gsub("%*%*([^%*\n]+)%*%*", "<b>%1</b>")
	text = text:gsub("__([^_\n]+)__", "<b>%1</b>")
	text = text:gsub("(%s)%*([^%*\n]+)%*", "%1<i>%2</i>")

	-- Headings become bold lead-ins.
	text = text:gsub("(\n#+)%s*([^\n]+)", function(marks, heading)
		return marks .. " <b>" .. heading .. "</b>"
	end)

	return text
end

--- Pulls the next renderable token: a single glyph, or a whole RichText tag.
local function nextToken(rich, index)
	local char = rich:sub(index, index)

	if char == "<" then
		local close = rich:find(">", index, true)
		if close then
			return rich:sub(index, close), close + 1, true
		end
	end

	return char, index + 1, false
end

--[[
	Renders `text` into `label` one character at a time.

	options = {
		speed      = number   -- seconds per character (default 0.03)
		sound      = boolean  -- click FX per glyph (default true)
		rich       = boolean  -- convert markdown to RichText (default true)
		onComplete = function(handle)
	}

	Returns a handle: { finished, skipped, text, skip(), await() }
]]
function Typewriter.play(label, text, options)
	options = options or {}

	local speed = options.speed or Typewriter.SPEED
	local plain = tostring(text or "")
	local rich = options.rich == false and plain or Typewriter.toRichText(plain)

	local generation = (label:GetAttribute("TypewriterGeneration") or 0) + 1
	label:SetAttribute("TypewriterGeneration", generation)
	label.RichText = true
	label.Text = ""

	local handle = {
		finished = false,
		skipped = false,
		text = plain,
		label = label,
		generation = generation,
	}

	function handle.skip()
		if not handle.finished then
			handle.skipped = true
		end
	end

	function handle.await()
		while not handle.finished do
			task.wait()
		end
	end

	local soundEnabled = options.sound ~= false
	local soundInstance = soundEnabled and sound() or nil

	task.spawn(function()
		local buffer = {}
		local index = 1
		local length = #rich

		while index <= length do
			-- A newer render on the same label wins.
			if label:GetAttribute("TypewriterGeneration") ~= generation then
				return
			end

			if handle.skipped then
				label.Text = rich
				handle.finished = true
				if options.onComplete then
					options.onComplete(handle)
				end
				return
			end

			local token, nextIndex, isTag = nextToken(rich, index)
			table.insert(buffer, token)
			index = nextIndex
			label.Text = table.concat(buffer)

			if not isTag then
				if soundInstance and token:match("%S") and soundInstance.Volume > 0 then
					soundInstance:Play()
				end

				if speed > 0 then
					task.wait(speed)
				end
			end
		end

		handle.finished = true
		if options.onComplete then
			options.onComplete(handle)
		end
	end)

	return handle
end

--- Clicking the dialogue frame instantly reveals the full block (spec §3).
function Typewriter.bindSkip(frame, handle)
	return frame.InputBegan:Connect(function(input)
		if
			input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch
		then
			handle.skip()
		end
	end)
end

--- Tears down the shared click sound (called on unload).
function Typewriter.destroy()
	if clickSound then
		pcall(function()
			clickSound:Destroy()
		end)
		clickSound = nil
	end
end

--- Convenience: render into a fresh label and return both.
function Typewriter.into(parent, text, role, options)
	local label = Fonts.autoSized(role or "body", { Parent = parent })
	local handle = Typewriter.play(label, text, options)
	return label, handle
end

return Typewriter
end

__modules["core/Util"] = function(require)
--[[
	core/Util.lua
	Shared helpers: instance construction, tweening, executor environment
	lookups and small text utilities.
	Spec: idea/main.md (layout), idea/backend.md (executor environment).
]]

local TweenService = game:GetService("TweenService")

local Util = {}

-- Environment -----------------------------------------------------------------

--- Returns the executor's global environment when available, else _G.
function Util.environment()
	local env

	if type(getgenv) == "function" then
		local ok, result = pcall(getgenv)
		if ok and type(result) == "table" then
			env = result
		end
	end

	return env or _G or {}
end

--- Safe lookup for executor-exclusive globals (writefile, request, ...).
function Util.global(name)
	local direct = _G[name]
	if direct ~= nil then
		return direct
	end

	return Util.environment()[name]
end

--- Wraps a privileged global so callers never have to pcall by hand.
function Util.call(name, ...)
	local fn = Util.global(name)
	if type(fn) ~= "function" then
		return false, nil
	end

	local results = table.pack(pcall(fn, ...))
	if not results[1] then
		return false, results[2]
	end

	return true, table.unpack(results, 2, results.n)
end

--- True when the script is running inside an exploit/executor sandbox.
function Util.isExecutor()
	return type(Util.global("writefile")) == "function"
		or type(Util.global("request")) == "function"
		or type(Util.global("getcustomasset")) == "function"
end

-- Instances -------------------------------------------------------------------

--- Instance.new with declarative props + children. `Parent` is applied last so
--- children never briefly reparent to the DataModel.
function Util.create(className, props, children)
	local instance = Instance.new(className)

	if props then
		for key, value in pairs(props) do
			if key ~= "Parent" then
				instance[key] = value
			end
		end
	end

	if children then
		for _, child in ipairs(children) do
			if child then
				child.Parent = instance
			end
		end
	end

	if props and props.Parent then
		instance.Parent = props.Parent
	end

	return instance
end

--- textlabel/textbutton/textbox with font + colour applied in one call.
function Util.text(className, props, children)
	return Util.create(className, props, children)
end

function Util.clear(instance)
	for _, child in ipairs(instance:GetChildren()) do
		child:Destroy()
	end
end

function Util.find(parent, name)
	return parent and parent:FindFirstChild(name) or nil
end

--- PlayerGui for the local player, which is where every ScreenGui lives.
function Util.guiParent()
	local player = game:GetService("Players").LocalPlayer
	if not player then
		return nil
	end

	return player:FindFirstChildOfClass("PlayerGui") or player:WaitForChild("PlayerGui", 10)
end

-- Decorators ------------------------------------------------------------------

function Util.corner(radius)
	return Util.create("UICorner", { CornerRadius = UDim.new(0, radius or 6) })
end

function Util.stroke(color, thickness, transparency)
	return Util.create("UIStroke", {
		Color = color or Color3.fromRGB(48, 54, 61),
		Thickness = thickness or 1,
		Transparency = transparency or 0,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
	})
end

function Util.padding(all, right, bottom, left)
	local uniform = all or 8
	return Util.create("UIPadding", {
		PaddingTop = UDim.new(0, uniform),
		PaddingRight = UDim.new(0, right or uniform),
		PaddingBottom = UDim.new(0, bottom or uniform),
		PaddingLeft = UDim.new(0, left or uniform),
	})
end

function Util.list(props)
	return Util.create("UIListLayout", props or {})
end

function Util.grid(props)
	return Util.create("UIGridLayout", props or {})
end

function Util.aspect(ratio)
	return Util.create("UIAspectRatioConstraint", {
		AspectRatio = ratio or 1,
		AspectType = Enum.AspectType.FitWithinMaxSize,
		DominantAxis = Enum.DominantAxis.Width,
	})
end

function Util.gradient(colorSequence, rotation)
	return Util.create("UIGradient", {
		Color = colorSequence,
		Rotation = rotation or 90,
	})
end

-- Motion ----------------------------------------------------------------------

function Util.tween(instance, props, duration, style, direction)
	local info = TweenInfo.new(
		duration or 0.15,
		style or Enum.EasingStyle.Quad,
		direction or Enum.EasingDirection.Out
	)
	return TweenService:Create(instance, info, props)
end

function Util.animate(instance, props, duration, style, direction)
	local tween = Util.tween(instance, props, duration, style, direction)
	tween:Play()
	return tween
end

function Util.connect(signal, callback)
	return signal:Connect(callback)
end

--- Groups connections so a panel can tear them all down at once.
function Util.connections()
	local group = {}

	function group.add(signal, callback)
		local connection = signal:Connect(callback)
		table.insert(group, connection)
		return connection
	end

	function group.destroy()
		for _, connection in ipairs(group) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(group)
	end

	return group
end

-- Text ------------------------------------------------------------------------

function Util.hex(value)
	local text = tostring(value):gsub("#", "")
	if #text ~= 6 then
		return Color3.fromRGB(255, 255, 255)
	end

	return Color3.fromRGB(
		tonumber(text:sub(1, 2), 16) or 0,
		tonumber(text:sub(3, 4), 16) or 0,
		tonumber(text:sub(5, 6), 16) or 0
	)
end

function Util.trim(text)
	return (tostring(text):gsub("^%s+", ""):gsub("%s+$", ""))
end

function Util.startsWith(text, prefix)
	return text:sub(1, #prefix) == prefix
end

function Util.clamp(value, minimum, maximum)
	return math.max(minimum, math.min(maximum, value))
end

--- Wraps a function so it cannot fire more than once per `delay` seconds.
function Util.debounce(delay, callback)
	local last = 0

	return function(...)
		local now = os.clock()
		if now - last < (delay or 0.2) then
			return nil
		end

		last = now
		return callback(...)
	end
end

function Util.timestamp()
	return os.date("%H:%M:%S")
end

--- Truncates on a word boundary where possible.
function Util.truncate(text, limit)
	if #text <= limit then
		return text
	end

	local cut = text:sub(1, limit)
	local space = cut:match("^(.+)%s")
	return (space or cut) .. "..."
end

return Util
end

__modules["init"] = function(require)
--[[
	init.lua
	Entry point for the Rick & Morty AI Executor.

	Boot order:
	  1. re-run safety: unload any previous instance
	  2. load persisted config (companion, provider, keys, onboarding flag)
	  3. build the ScreenGui, notifications, quick menu and dashboard
	  4. first run: start the onboarding tour; otherwise stay collapsed to the anchor

	Public API (also exposed as `getgenv().RickMortyAI`):
	  :Open()            :Close()          :Toggle()
	  :ToggleQuickMenu() :SetCompanion(n)  :Unload()
]]

local Assets = require("core/Assets")
local Http = require("core/Http")
local Notify = require("ui/Notify")
local Palette = require("core/Palette")
local State = require("core/State")
local Tutorial = require("ui/Tutorial")
local Typewriter = require("core/Typewriter")
local Util = require("core/Util")

local Dashboard = require("ui/Dashboard")
local QuickMenu = require("ui/QuickMenu")

local app = {}

app.version = "1.0.0"
app.gui = nil
app.dashboard = nil
app.quickMenu = nil
app.tutorial = nil
app.sidebar = nil

-- Small helpers ---------------------------------------------------------------

local function environment()
	return Util.environment()
end

-- API -------------------------------------------------------------------------

function app.notify(title, body, variant)
	return Notify.toast({
		Title = title,
		Body = body,
		Variant = variant or "info",
	})
end

function app.Open()
	if app.dashboard then
		app.dashboard:setVisible(true)
		app.dashboard:refresh()
	end
end

function app.Close()
	if app.dashboard then
		app.dashboard:setVisible(false)
	end
end

function app.Toggle()
	if app.dashboard then
		app.dashboard:toggle()
	end
end

function app.ToggleQuickMenu()
	if app.quickMenu then
		app.quickMenu:toggle()
	end
end

function app.SetCompanion(name)
	State.setCompanion(name)
	app.OnCompanionChanged(name)
end

--- Re-skins every companion surface after a Rick/Morty switch.
function app.OnCompanionChanged(name)
	if app.dashboard then
		app.dashboard:refresh()
	end

	-- Stay quiet while the onboarding tour is driving the switch itself.
	if app.notify and name and not app.tutorial then
		local theme = Palette.character(name)
		app.notify("Companion switched", theme.label .. " // " .. theme.tagline, "info")
	end
end

--- Restores an archived conversation into the chat pane.
function app.OnHistoryRestored()
	if app.dashboard then
		app.dashboard:setTab("Chat")
		app.dashboard.panels.Chat:render()
	end
end

function app.Unload()
	if app.quickMenu then
		pcall(function()
			app.quickMenu:destroy()
		end)
		app.quickMenu = nil
	end

	Typewriter.destroy()

	if app.dashboard then
		pcall(function()
			app.dashboard:destroy()
		end)
		app.dashboard = nil
	end

	if app.gui then
		pcall(function()
			app.gui:Destroy()
		end)
		app.gui = nil
	end

	local env = environment()
	if env.RickMortyAI == app then
		env.RickMortyAI = nil
	end

	app.unloaded = true
end

-- Boot ------------------------------------------------------------------------

function app.init()
	-- Only one instance at a time.
	local env = environment()
	local existing = env.RickMortyAI
	if existing and existing ~= app and type(existing.Unload) == "function" then
		pcall(existing.Unload)
	end

	State.load()

	local parent = Util.guiParent()
	if not parent then
		warn("[RickMortyAI] no PlayerGui yet; aborting.")
		return app
	end

	app.gui = Util.create("ScreenGui", {
		Name = "RickMortyAI",
		ResetOnSpawn = false,
		IgnoreGuiInset = true,
		DisplayOrder = 100,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		Parent = parent,
	})

	Notify.setup(app.gui)

	app.quickMenu = QuickMenu.new(app.gui, app)
	app.dashboard = Dashboard.new(app.gui, app)

	if not State.data.onboarded then
		app.dashboard:setVisible(true)

		app.tutorial = Tutorial.start(app.gui, app, function()
			app.tutorial = nil
			app.notify(
				"Setup complete",
				"Press ';' anywhere for the quick menu, or click the AI CONSOLE anchor to reopen this window.",
				"ok"
			)
		end)
	else
		app.dashboard:setVisible(false)
	end

	-- Warn when the PNGs were not shipped beside the script.
	if Util.isExecutor() then
		local missing = Assets.missingNames()
		if #missing > 0 then
			app.notify(
				"Artwork not found",
				"Missing " .. table.concat(missing, ", ") .. ". Drop them beside the executor's workspace folder (or in imgs/) and re-run.",
				"warn"
			)
		end
	end

	local transport = Http.transportName()
	app.notify(
		"Rick & Morty AI Executor v" .. app.version,
		"Press ';' for the quick menu."
			.. "\nTransport: "
			.. transport
			.. "\nCompanion: "
			.. State.companion()
			.. " // "
			.. State.provider(),
		Http.available() and "info" or "warn"
	)

	env.RickMortyAI = app
	app.unloaded = false

	return app
end

app.init()

return app
end

__modules["ui/ChatPanel"] = function(require)
--[[
	ui/ChatPanel.lua
	Chat mode: conversational pane for instructing the AI to write, debug or
	patch Luau blocks (idea/ui-creation.md §3).

	Replies stream in through the typewriter and any fenced code block gets an
	inline "Execute" affordance that routes into the Code runner.
]]

local Chat = require("core/Chat")
local CodeRunner = require("core/CodeRunner")
local Components = require("ui/Components")
local Fonts = require("core/Fonts")
local Palette = require("core/Palette")
local Providers = require("core/Providers")
local State = require("core/State")
local Typewriter = require("core/Typewriter")
local Util = require("core/Util")

local ChatPanel = {}

function ChatPanel.new(parent, app)
	local frame = Util.create("Frame", {
		Name = "ChatPanel",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, 0),
		Parent = parent,
	})

	-- Header ------------------------------------------------------------------

	local header = Util.create("Frame", {
		Name = "Header",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -24, 0, 32),
		Position = UDim2.new(0, 12, 0, 10),
		Parent = frame,
	}, {
		Util.list({
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 8),
			VerticalAlignment = Enum.VerticalAlignment.Center,
		}),
	})

	local companionBadge = Components.badge({
		Name = "CompanionBadge",
		Text = string.upper(State.companion()),
		LayoutOrder = 1,
		Parent = header,
	})

	local providerBadge = Components.badge({
		Name = "ProviderBadge",
		Text = State.provider(),
		Color = Palette.neon.cyan,
		LayoutOrder = 2,
		Parent = header,
	})

	-- Fixed offset width: a scale-width child inside a horizontal UIListLayout
	-- would stretch and shove the trailing buttons off the row.
	local status = Fonts.new("TextLabel", "small", {
		Name = "Status",
		Text = "ready",
		TextColor3 = Palette.text.dim,
		TextSize = 11,
		BackgroundTransparency = 1,
		Size = UDim2.new(0, 180, 1, 0),
		TextXAlignment = Enum.TextXAlignment.Right,
		TextYAlignment = Enum.TextYAlignment.Center,
		LayoutOrder = 3,
		Parent = header,
	})

	Components.button({
		Name = "Reset",
		Text = "New chat",
		Variant = "dark",
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 4,
		Parent = header,
		OnClick = function()
			State.resetHistory()
			panel:clear()
			panel:setStatus("conversation archived")
		end,
	})

	-- Transcript --------------------------------------------------------------

	local transcript = Components.scroll({
		Name = "Transcript",
		Size = UDim2.new(1, -8, 1, -166),
		Position = UDim2.new(0, 4, 0, 50),
		Padding = 14,
		Inset = 8,
		Parent = frame,
	})

	-- Composer ----------------------------------------------------------------

	local composer = Util.create("Frame", {
		Name = "Composer",
		BackgroundColor3 = Palette.surfaces.panel,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -24, 0, 96),
		Position = UDim2.new(0, 12, 1, -108),
		Parent = frame,
	}, {
		Util.corner(10),
		Util.stroke(Palette.surfaces.border, 1, 0.3),
		Util.padding(10),
	})

	local input = Components.input({
		Name = "Prompt",
		Placeholder = "Ask for a Luau script, a patch, or a refactor...",
		MultiLine = true,
		Wrap = true,
		Size = UDim2.new(1, -96, 1, 0),
		Parent = composer,
		OnSubmit = function(_, enterPressed)
			if enterPressed then
				panel:submit()
			end
		end,
	})

	local sendButton
	sendButton = Components.button({
		Name = "Send",
		Text = "Send",
		Variant = "green",
		Size = UDim2.new(0, 84, 1, 0),
		Position = UDim2.new(1, 0, 0, 0),
		AnchorPoint = Vector2.new(1, 0),
		Parent = composer,
		OnClick = function()
			panel:submit()
		end,
	})

	local hint = Fonts.new("TextLabel", "small", {
		Name = "Hint",
		Text = "Enter sends  |  replies auto-detect ```lua blocks  |  the persona prompt stays hidden",
		TextColor3 = Palette.text.dim,
		TextSize = 10,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -24, 0, 14),
		Position = UDim2.new(0, 14, 1, -18),
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = frame,
	})

	-- Turns -------------------------------------------------------------------

	local order = 0
	local thinking = false

	local function stopThinking()
		thinking = false
	end

	local function startThinking()
		thinking = true
		task.spawn(function()
			local frames = { "", ".", "..", "..." }
			local index = 1
			while thinking do
				status.Text = string.upper(State.companion()) .. " is thinking" .. frames[index]
				index = index % #frames + 1
				task.wait(0.4)
			end
		end)
	end

	local function addTurn(role, text, opts)
		opts = opts or {}
		order += 1

		local isUser = role == "user"
		local theme = Palette.character(State.companion())

		local turn = Util.create("Frame", {
			Name = role,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = order,
			Parent = transcript,
		}, {
			Util.list({ Padding = UDim.new(0, 6) }),
		})

		Fonts.new("TextLabel", "small", {
			Name = "Author",
			Text = isUser and "OPERATOR" or string.upper(State.companion()),
			TextColor3 = isUser and Palette.text.dim or theme.text,
			TextSize = 10,
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 14),
			TextXAlignment = Enum.TextXAlignment.Left,
			LayoutOrder = 1,
			Parent = turn,
		})

		local bubble = Components.panel({
			Name = "Bubble",
			BackgroundColor3 = isUser and Palette.surfaces.card or Palette.surfaces.panel,
			StrokeColor = isUser and Palette.surfaces.border or theme.glow,
			StrokeTransparency = isUser and 0.4 or 0.55,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 2,
			Parent = turn,
		}, {
			Util.padding(12),
			Util.list({ Padding = UDim.new(0, 8) }),
		})

		local body = Fonts.new("TextLabel", "body", {
			Name = "Body",
			Text = "",
			RichText = true,
			TextColor3 = Palette.text.primary,
			BackgroundTransparency = 1,
			AutomaticSize = Enum.AutomaticSize.Y,
			Size = UDim2.new(1, 0, 0, 0),
			TextWrapped = true,
			LayoutOrder = 1,
			Parent = bubble,
		})

		if opts.animate then
			local handle = Typewriter.play(body, text)
			Typewriter.bindSkip(bubble, handle)
		else
			body.Text = Typewriter.toRichText(text)
		end

		-- Inline actions for assistant turns that carry code.
		if not isUser and CodeRunner.looksLikeCode(text) then
			local actions = Util.create("Frame", {
				Name = "Actions",
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Size = UDim2.new(1, 0, 0, 26),
				LayoutOrder = 2,
				Parent = bubble,
			}, {
				Util.list({
					FillDirection = Enum.FillDirection.Horizontal,
					Padding = UDim.new(0, 6),
					VerticalAlignment = Enum.VerticalAlignment.Center,
				}),
			})

			Components.button({
				Name = "Execute",
				Text = "Execute",
				Variant = "green",
				Size = UDim2.new(0, 0, 1, 0),
				AutomaticSize = Enum.AutomaticSize.X,
				LayoutOrder = 1,
				Parent = actions,
				OnClick = function()
					local ok, output = CodeRunner.execute(text)
					if app and app.notify then
						app.notify(ok and "Executed" or "Execution failed", tostring(output ~= "" and output or "script finished"))
					end
					if app and app.dashboard then
						app.dashboard:log(ok and ("[executed] " .. tostring(output)) or ("[error] " .. tostring(output)), ok and "ok" or "error")
					end
				end,
			})

			Components.button({
				Name = "SendToCode",
				Text = "Open in Code",
				Variant = "dark",
				Size = UDim2.new(0, 0, 1, 0),
				AutomaticSize = Enum.AutomaticSize.X,
				LayoutOrder = 2,
				Parent = actions,
				OnClick = function()
					if app and app.dashboard then
						app.dashboard:setTab("Code")
						app.dashboard:loadCode(CodeRunner.stripFences(CodeRunner.extractCode(text) or text))
					end
				end,
			})
		end

		task.defer(function()
			transcript.CanvasPosition = Vector2.new(0, math.max(0, transcript.AbsoluteCanvasSize.Y))
		end)

		return turn
	end

	-- Panel API ---------------------------------------------------------------

	local panel = {
		frame = frame,
		transcript = transcript,
		input = input,
	}

	function panel:setStatus(text, kind)
		status.Text = text
		status.TextColor3 = kind == "error" and Palette.neon.pink
			or kind == "ok" and Palette.neon.green
			or Palette.text.dim
	end

	function panel:addUser(text)
		return addTurn("user", text)
	end

	function panel:addAssistant(text, animate)
		return addTurn("assistant", text, { animate = animate })
	end

	function panel:clear()
		Util.clear(transcript)
		order = 0
	end

	--- Re-renders the stored history without animation.
	function panel:render()
		panel:clear()
		for _, message in ipairs(State.history) do
			if message.role ~= "system" then
				addTurn(message.role, message.content)
			end
		end
	end

	function panel:refresh()
		companionBadge.TextLabel.Text = string.upper(State.companion())
		providerBadge.TextLabel.Text = State.provider()
		providerBadge.TextLabel.TextColor3 = Palette.neon.cyan
	end

	function panel:focusInput()
		input:CaptureFocus()
	end

	function panel:setPrompt(text)
		input.Text = text
		input:CaptureFocus()
	end

	function panel:submit(text)
		local prompt = Util.trim(text or input.Text)
		if prompt == "" then
			return
		end

		input.Text = ""
		panel:addUser(prompt)

		local provider = Providers.get(State.provider())
		if provider.style ~= "freebuff" and State.apiKey(State.provider()) == "" and State.provider() ~= "AgentRouter" then
			panel:setStatus("warning: no API key set for " .. State.provider(), "error")
		end

		startThinking()

		Chat.send(prompt, {
			onDone = function(reply)
				stopThinking()
				panel:addAssistant(reply, true)
				panel:setStatus("replied", "ok")
			end,
			onError = function(message)
				stopThinking()
				panel:addAssistant("**Request failed**\n\n" .. tostring(message))
				panel:setStatus("request failed", "error")
			end,
			onFinish = function()
				stopThinking()
				if app and app.sidebar then
					app.sidebar:refreshSessions()
				end
			end,
		})
	end

	return panel
end

return ChatPanel
end

__modules["ui/CodePanel"] = function(require)
--[[
	ui/CodePanel.lua
	Code mode: the on-screen executor from idea/ui-creation.md §3 — monospace
	editor with a live line gutter, raw script testing and an output console.

	Note: the gutter is a plain label, so it does not scroll in lockstep with
	the TextBox. Line counts stay correct because the gutter is rebuilt from the
	editor's contents on every change.
]]

local Chat = require("core/Chat")
local CodeRunner = require("core/CodeRunner")
local Components = require("ui/Components")
local Fonts = require("core/Fonts")
local Palette = require("core/Palette")
local State = require("core/State")
local Util = require("core/Util")

local CodePanel = {}

local SAMPLE = [[-- Rick & Morty AI Executor // sample script
local portal = Instance.new("Part")
portal.Name = "PortalTest"
portal.Shape = Enum.PartType.Ball
portal.Material = Enum.Material.Neon
portal.Color = Color3.fromRGB(0, 255, 136)
portal.Size = Vector3.new(4, 4, 4)
portal.Position = Vector3.new(0, 6, 0)
portal.Anchored = true
portal.Parent = workspace

print("RickMortyAI sample executed at " .. os.date("%H:%M:%S"))
]]

function CodePanel.new(parent, app)
	local frame = Util.create("Frame", {
		Name = "CodePanel",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, 0),
		Parent = parent,
	})

	-- Toolbar -----------------------------------------------------------------

	local toolbar = Util.create("Frame", {
		Name = "Toolbar",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -24, 0, 32),
		Position = UDim2.new(0, 12, 0, 10),
		Parent = frame,
	}, {
		Util.list({
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 6),
			VerticalAlignment = Enum.VerticalAlignment.Center,
		}),
	})

	-- Fixed offset width: a scale-width child inside a horizontal UIListLayout
	-- would stretch and shove the trailing buttons off the row.
	local status = Fonts.new("TextLabel", "small", {
		Name = "Status",
		Text = "idle",
		TextColor3 = Palette.text.dim,
		TextSize = 11,
		BackgroundTransparency = 1,
		Size = UDim2.new(0, 170, 1, 0),
		TextXAlignment = Enum.TextXAlignment.Right,
		TextYAlignment = Enum.TextYAlignment.Center,
		LayoutOrder = 90,
		Parent = toolbar,
	})

	-- Editor ------------------------------------------------------------------

	local editor = Util.create("Frame", {
		Name = "Editor",
		BackgroundColor3 = Palette.surfaces.background,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -24, 0.55, 0),
		Position = UDim2.new(0, 12, 0, 50),
		Parent = frame,
	}, {
		Util.corner(8),
		Util.stroke(Palette.surfaces.border, 1, 0.2),
	})

	local gutter = Fonts.new("TextLabel", "code", {
		Name = "Gutter",
		Text = "1",
		TextColor3 = Palette.text.dim,
		TextSize = 12,
		BackgroundTransparency = 1,
		Size = UDim2.new(0, 40, 1, -16),
		Position = UDim2.new(0, 8, 0, 8),
		TextXAlignment = Enum.TextXAlignment.Right,
		TextYAlignment = Enum.TextYAlignment.Top,
		Parent = editor,
	})

	local box = Components.input({
		Name = "Source",
		MultiLine = true,
		Placeholder = "-- paste Luau here, or generate code from the Chat tab",
		Role = "code",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -66, 1, -12),
		Position = UDim2.new(0, 56, 0, 6),
		Parent = editor,
		Wrap = false,
	})

	local function refreshGutter()
		local count = 1
		for _ in string.gmatch(box.Text, "\n") do
			count += 1
		end

		local numbers = {}
		for index = 1, count do
			table.insert(numbers, tostring(index))
		end
		gutter.Text = table.concat(numbers, "\n")
	end

	box:GetPropertyChangedSignal("Text"):Connect(refreshGutter)

	-- Console -----------------------------------------------------------------

	local console = Components.console({
		Name = "Console",
		Size = UDim2.new(1, -24, 0.45, -76),
		Position = UDim2.new(0, 12, 0, 50),
		Parent = frame,
	})

	console.Position = UDim2.new(0, 12, 1, -1)
	console.AnchorPoint = Vector2.new(0, 1)
	console.Size = UDim2.new(1, -24, 0.45, -60)

	-- Actions -----------------------------------------------------------------

	local panel = {
		frame = frame,
		editor = editor,
		console = console,
	}

	function panel:setStatus(text, kind)
		status.Text = text
		status.TextColor3 = kind == "error" and Palette.neon.pink
			or kind == "ok" and Palette.neon.green
			or Palette.text.dim
	end

	function panel:log(text, kind)
		console:Append(text, kind)
	end

	function panel:setSource(text)
		box.Text = text or ""
		refreshGutter()
	end

	function panel:getSource()
		return box.Text
	end

	function panel:clearConsole()
		console:Clear()
		panel:setStatus("console cleared")
	end

	function panel:run()
		local source = Util.trim(box.Text)
		if source == "" then
			panel:setStatus("nothing to run", "error")
			return
		end

		panel:log("> execute (" .. tostring(select(2, string.gsub(source, "\n", "")) + 1) .. " lines)", "info")

		local ok, output = CodeRunner.execute(source, { name = "code_pane_" .. tostring(os.time()) })
		if ok then
			panel:log(tostring(output ~= "" and output or "script finished"), "ok")
			panel:setStatus("executed", "ok")
		else
			panel:log(tostring(output), "error")
			panel:setStatus("execution failed", "error")
		end
	end

	function panel:extractLastReply()
		for index = #State.history, 1, -1 do
			local message = State.history[index]
			if message.role == "assistant" then
				local code = CodeRunner.extractCode(message.content)
				if code then
					panel:setSource(code)
					panel:setStatus("pulled latest reply into the editor", "ok")
				else
					panel:setStatus("latest reply has no code block", "error")
				end
				return
			end
		end

		panel:setStatus("no assistant reply yet", "error")
	end

	--- Sends the current editor contents through the AI for a review pass.
	function panel:askForReview()
		local source = Util.trim(box.Text)
		if source == "" then
			panel:setStatus("nothing to review", "error")
			return
		end

		panel:setStatus("requesting review...")
		Chat.send("Review and fix this Luau for Roblox, then return the corrected script in a ```lua block:\n\n```lua\n" .. source .. "\n```", {
			onDone = function(reply)
				panel:log("[review]\n" .. reply, "info")
				local code = CodeRunner.extractCode(reply)
				if code then
					panel:setSource(code)
					panel:setStatus("review applied to the editor", "ok")
				end
			end,
			onError = function(message)
				panel:log("[error] " .. tostring(message), "error")
				panel:setStatus("review failed", "error")
			end,
		})
	end

	-- Toolbar wiring ----------------------------------------------------------

	local actions = {
		{ label = "Run", variant = "green", onClick = function() panel:run() end },
		{ label = "From chat", variant = "dark", onClick = function() panel:extractLastReply() end },
		{ label = "Review", variant = "dark", onClick = function() panel:askForReview() end },
		{ label = "Sample", variant = "dark", onClick = function() panel:setSource(SAMPLE) end },
		{ label = "Clear", variant = "dark", onClick = function()
			panel:setSource("")
			panel:clearConsole()
		end },
	}

	for index, action in ipairs(actions) do
		Components.button({
			Name = action.label,
			Text = action.label,
			Variant = action.variant,
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			LayoutOrder = index,
			Parent = toolbar,
			OnClick = action.onClick,
		})
	end

	-- Seed with the sample so the pane is never empty on first open.
	panel:setSource(SAMPLE)
	panel:log("Rick & Morty AI Executor // code pane ready", "info")

	return panel
end

return CodePanel
end

__modules["ui/Companion"] = function(require)
--[[
	ui/Companion.lua
	The "little buddy" overlay from idea/png-usage.md §2.

	  * 64x64 frame, ScaleType = Fit
	  * ZIndex 5 so it floats above message bubbles without clipping text
	  * hover applies a neon scaling bump to 70x70 through TweenService
	  * the tutorial reuses this at 128x128 as the guide anchor
]]

local Assets = require("core/Assets")
local Palette = require("core/Palette")
local State = require("core/State")
local Util = require("core/Util")

local Companion = {}

Companion.SIZE = 64
Companion.HOVER_SIZE = 70
Companion.GUIDE_SIZE = 128

--[[
	Creates the portrait overlay.

	props = { Name = "Rick"|"Morty", Size, Position, AnchorPoint, Parent,
	          Hover = boolean, ZIndex, ShowPlate = boolean }
]]
function Companion.create(parent, props)
	props = props or {}

	local companionName = props.Name or State.companion()
	local size = props.Size or Companion.SIZE
	local theme = Palette.character(companionName)

	local frame = Util.create("Frame", {
		Name = "Companion",
		BackgroundColor3 = Palette.surfaces.card,
		BackgroundTransparency = 0.35,
		BorderSizePixel = 0,
		Size = UDim2.new(0, size, 0, size),
		Position = props.Position or UDim2.new(1, -16, 1, -16),
		AnchorPoint = props.AnchorPoint or Vector2.new(1, 1),
		ZIndex = props.ZIndex or 5,
		LayoutOrder = props.LayoutOrder,
		Parent = parent,
	})

	Util.corner(math.max(6, size * 0.12)).Parent = frame

	local stroke = Util.stroke(theme.glow, 1, 0.25)
	stroke.Parent = frame

	local portrait = Assets.imageLabel(string.lower(companionName), {
		Name = "Portrait",
		Image = Assets.portrait(companionName),
		Size = UDim2.new(1, -6, 1, -6),
		Position = UDim2.new(0, 3, 0, 3),
		ScaleType = Enum.ScaleType.Fit,
		ZIndex = (props.ZIndex or 5) + 1,
		Parent = frame,
	})

	local plate
	if props.ShowPlate then
		plate = Util.create("TextLabel", {
			Name = "Plate",
			BackgroundColor3 = Palette.surfaces.background,
			BackgroundTransparency = 0.15,
			BorderSizePixel = 0,
			Text = string.upper(companionName),
			TextColor3 = theme.text,
			TextSize = 10,
			Font = Enum.Font.GothamBold,
			Size = UDim2.new(1, 8, 0, 14),
			Position = UDim2.new(0.5, 0, 1, 3),
			AnchorPoint = Vector2.new(0.5, 0),
			ZIndex = (props.ZIndex or 5) + 2,
			Parent = frame,
		})
		Util.corner(4).Parent = plate
	end

	-- Hover: neon scaling bump (idea/png-usage.md §2).
	local hoverEnabled = props.Hover ~= false
	if hoverEnabled then
		local baseSize = size
		local hoverSize = math.max(size + 6, math.floor(baseSize * (Companion.HOVER_SIZE / Companion.SIZE)))

		frame.MouseEnter:Connect(function()
			Util.animate(frame, {
				Size = UDim2.new(0, hoverSize, 0, hoverSize),
				BackgroundTransparency = 0.15,
			}, 0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out)

			Util.animate(stroke, { Transparency = 0 }, 0.18)
		end)

		frame.MouseLeave:Connect(function()
			Util.animate(frame, {
				Size = UDim2.new(0, baseSize, 0, baseSize),
				BackgroundTransparency = 0.35,
			}, 0.18)

			Util.animate(stroke, { Transparency = 0.25 }, 0.18)
		end)
	end

	frame.Portrait = portrait
	frame.Stroke = stroke
	frame.Plate = plate

	--- Morphs this overlay onto another companion profile.
	function frame:SetCharacter(companionName2)
		local nextTheme = Palette.character(companionName2)
		portrait.Image = Assets.portrait(companionName2)
		stroke.Color = nextTheme.glow
		if plate then
			plate.Text = string.upper(nextTheme.name)
			plate.TextColor3 = nextTheme.text
		end
	end

	return frame
end

--- Bigger framed portrait used by the onboarding guide.
function Companion.guide(parent, companionName, props)
	props = props or {}
	props.Name = companionName
	props.Size = props.Size or Companion.GUIDE_SIZE
	props.Hover = false
	props.ShowPlate = true
	props.ZIndex = props.ZIndex or 6

	local frame = Companion.create(parent, props)

	-- A soft glow ring keeps the guide visually anchored to the dialogue box.
	local glow = Util.create("Frame", {
		Name = "Glow",
		BackgroundColor3 = Palette.character(companionName).glow,
		BackgroundTransparency = 0.85,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 12, 1, 12),
		Position = UDim2.new(0.5, 0, 0.5, 0),
		AnchorPoint = Vector2.new(0.5, 0.5),
		ZIndex = (props.ZIndex or 6) - 1,
		Parent = frame,
	})
	Util.corner(999).Parent = glow

	return frame
end

return Companion
end

__modules["ui/Components"] = function(require)
--[[
	ui/Components.lua
	Reusable widgets built from the palette spec. Every interactive component
	walks the idle -> hover -> pressed sequence defined in
	idea/colour-palette.md §4.
]]

local Fonts = require("core/Fonts")
local Palette = require("core/Palette")
local Util = require("core/Util")

local Components = {}

local function merge(base, overrides)
	local result = {}
	for key, value in pairs(base) do
		result[key] = value
	end
	if overrides then
		for key, value in pairs(overrides) do
			result[key] = value
		end
	end
	return result
end

-- Containers ------------------------------------------------------------------

-- Styling-only keys that must never be assigned to the Instance itself.
local PANEL_RESERVED = {
	Radius = true,
	Stroke = true,
	StrokeColor = true,
	StrokeTransparency = true,
}

--- Dark console card: card background, metallic border, rounded corners.
--- Every other prop is forwarded straight to the Instance.
function Components.panel(props, children)
	props = props or {}

	local config = {
		Name = "Panel",
		BackgroundColor3 = Palette.surfaces.card,
		BackgroundTransparency = 0,
		BorderSizePixel = 0,
	}

	for key, value in pairs(props) do
		if not PANEL_RESERVED[key] then
			config[key] = value
		end
	end

	local frame = Util.create("Frame", config, children)

	Util.corner(props.Radius or 8).Parent = frame
	if props.Stroke ~= false then
		Util.stroke(props.StrokeColor or Palette.surfaces.border, 1, props.StrokeTransparency or 0).Parent = frame
	end

	return frame
end

--- Transparent layout container (no background, no stroke).
function Components.row(props, children)
	props = props or {}
	return Util.create("Frame", merge({
		Name = "Row",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 36),
	}, props), children)
end

function Components.divider(props)
	props = props or {}
	return Util.create("Frame", {
		Name = "Divider",
		BackgroundColor3 = Palette.surfaces.border,
		BorderSizePixel = 0,
		BackgroundTransparency = 0.35,
		Size = props.Size or UDim2.new(1, 0, 0, 1),
		LayoutOrder = props.LayoutOrder,
		Parent = props.Parent,
	})
end

-- Text ------------------------------------------------------------------------

function Components.label(props)
	props = props or {}
	local config = merge({
		Name = "Label",
		BackgroundTransparency = 1,
		TextColor3 = Palette.text.primary,
		Text = "",
		Size = UDim2.new(1, 0, 0, 20),
	}, props)
	return Fonts.new("TextLabel", props.Role or "body", config)
end

--- Small uppercase chip used for provider/model metadata.
function Components.badge(props)
	props = props or {}
	local container = Util.create("Frame", {
		Name = "Badge",
		BackgroundColor3 = Palette.surfaces.card,
		BorderSizePixel = 0,
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.new(0, 0, 0, 22),
		LayoutOrder = props.LayoutOrder,
		Parent = props.Parent,
	})

	Util.corner(999).Parent = container
	Util.stroke(props.Color or Palette.surfaces.border, 1, 0.3).Parent = container
	Util.padding(0, 10, 0, 10).Parent = container

	local label = Fonts.new("TextLabel", "small", {
		Name = "Text",
		BackgroundTransparency = 1,
		Text = props.Text or "",
		TextColor3 = props.Color or Palette.text.secondary,
		TextSize = 11,
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		TextXAlignment = Enum.TextXAlignment.Center,
		TextYAlignment = Enum.TextYAlignment.Center,
		Parent = container,
	})

	container.TextLabel = label
	return container
end

-- Buttons ---------------------------------------------------------------------

--[[
	props = {
		Text, Variant ("dark"|"green"|"pink"|"cyan"), Accent (Color3 override),
		Size, Position, AnchorPoint, LayoutOrder, Parent, Radius, Role,
		OnClick, Disabled (bool), Tooltip
	}
]]
-- Behaviour keys that must never be assigned to the Instance itself.
local BUTTON_RESERVED = {
	Variant = true,
	Role = true,
	Radius = true,
	Disabled = true,
	OnClick = true,
}

function Components.button(props)
	props = props or {}

	local variant = props.Variant or "dark"
	local states = Palette.statesFor(variant)
	local textColor = (variant == "dark") and Palette.text.primary or Palette.text.inverse

	local config = {
		Name = "Button",
		Text = "",
		AutoButtonColor = false,
		BackgroundColor3 = props.Disabled and Palette.surfaces.panel or states.idle,
		TextTransparency = props.Disabled and 0.5 or 0,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 120, 0, 34),
		TextColor3 = props.TextColor3 or textColor,
	}

	-- Forward anything else (AutomaticSize, BackgroundTransparency, AnchorPoint,
	-- Position, LayoutOrder, Visible, ZIndex, Parent, ...) straight through.
	for key, value in pairs(props) do
		if not BUTTON_RESERVED[key] then
			config[key] = value
		end
	end

	local button = Util.create("TextButton", config, {
		Util.corner(props.Radius or 8),
		Util.stroke(states.stroke, 1, 0.45),
		Util.padding(6, 12, 6, 12),
	})

	Fonts.apply(button, props.Role or "button", {
		TextTruncate = props.TextTruncate or Enum.TextTruncate.AtEnd,
		TextXAlignment = props.TextXAlignment or Enum.TextXAlignment.Center,
		TextYAlignment = props.TextYAlignment or Enum.TextYAlignment.Center,
	})

	-- Buttons that were intentionally made transparent keep their transparency.
	local idleTransparency = config.BackgroundTransparency or 0

	local function tweenTo(color, transparency)
		if not button.Parent then
			return
		end
		Util.animate(button, {
			BackgroundColor3 = color,
			BackgroundTransparency = transparency == nil and idleTransparency or transparency,
		}, 0.12)
	end

	button.MouseEnter:Connect(function()
		if props.Disabled then
			return
		end
		tweenTo(states.hover)
	end)

	button.MouseLeave:Connect(function()
		tweenTo(props.Disabled and Palette.surfaces.panel or states.idle)
	end)

	button.MouseButton1Down:Connect(function()
		if props.Disabled then
			return
		end
		tweenTo(states.pressed)
	end)

	button.MouseButton1Up:Connect(function()
		if props.Disabled then
			return
		end
		tweenTo(states.hover)
	end)

	button.MouseButton1Click:Connect(function()
		if props.Disabled then
			return
		end

		if props.OnClick then
			local ok, err = pcall(props.OnClick)
			if not ok then
				warn("[RickMortyAI] button callback failed: " .. tostring(err))
			end
		end
	end)

	return button
end

function Components.accentButton(props)
	props = props or {}
	props.Variant = props.Variant or "green"
	return Components.button(props)
end

-- Inputs ----------------------------------------------------------------------

--[[
	props = { Text, Placeholder, Size, Parent, LayoutOrder, MultiLine, Role,
	          OnSubmit(text, enterPressed), OnChanged(text), ClearTextOnFocus }
]]
function Components.input(props)
	props = props or {}
	local multiLine = props.MultiLine == true

	local box = Util.create("TextBox", {
		Name = props.Name or "Input",
		Text = props.Text or "",
		PlaceholderText = props.Placeholder or "",
		PlaceholderColor3 = Palette.text.dim,
		TextColor3 = Palette.text.primary,
		BackgroundColor3 = Palette.surfaces.background,
		BackgroundTransparency = props.BackgroundTransparency or 0,
		BorderSizePixel = 0,
		ClearTextOnFocus = props.ClearTextOnFocus == true,
		MultiLine = multiLine,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = multiLine and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center,
		Size = props.Size or UDim2.new(1, 0, 0, 36),
		Position = props.Position,
		LayoutOrder = props.LayoutOrder,
		ZIndex = props.ZIndex,
		Parent = props.Parent,
	}, {
		Util.corner(props.Radius or 8),
		Util.stroke(Palette.surfaces.border, 1, 0.2),
		Util.padding(multiLine and 10 or 4, 10, multiLine and 10 or 4, 10),
	})

	Fonts.apply(box, props.Role or (multiLine and "code" or "body"), {
		TextWrapped = props.Wrap == true,
	})

	local stroke = box:FindFirstChildOfClass("UIStroke")

	box.Focused:Connect(function()
		if stroke then
			Util.animate(stroke, { Color = Palette.neon.green }, 0.12)
		end
	end)

	box.FocusLost:Connect(function(enterPressed)
		if stroke then
			Util.animate(stroke, { Color = Palette.surfaces.border }, 0.12)
		end
		if props.OnSubmit then
			local ok, err = pcall(props.OnSubmit, box.Text, enterPressed)
			if not ok then
				warn("[RickMortyAI] input submit failed: " .. tostring(err))
			end
		end
	end)

	if props.OnChanged then
		box:GetPropertyChangedSignal("Text"):Connect(function()
			props.OnChanged(box.Text)
		end)
	end

	return box
end

-- Scrolling -------------------------------------------------------------------

function Components.scroll(props)
	props = props or {}

	local frame = Util.create("ScrollingFrame", {
		Name = props.Name or "Scroll",
		BackgroundColor3 = props.BackgroundColor3 or Palette.surfaces.panel,
		BackgroundTransparency = props.BackgroundTransparency == nil and 1 or props.BackgroundTransparency,
		BorderSizePixel = 0,
		ScrollBarThickness = 4,
		ScrollBarImageColor3 = props.ScrollBarColor or Palette.surfaces.border,
		ScrollBarImageTransparency = 0.25,
		CanvasSize = UDim2.new(0, 0, 0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollingEnabled = true,
		ElasticBehavior = Enum.ElasticBehavior.WhenScrollable,
		Size = props.Size or UDim2.new(1, 0, 1, 0),
		Position = props.Position,
		LayoutOrder = props.LayoutOrder,
		Parent = props.Parent,
	}, {
		Util.list({
			Padding = UDim.new(0, props.Padding or 10),
			SortOrder = Enum.SortOrder.LayoutOrder,
			HorizontalAlignment = props.HorizontalAlignment or Enum.HorizontalAlignment.Left,
		}),
		Util.padding(props.Inset or 6),
	})

	if props.Stroke then
		Util.stroke(Palette.surfaces.border, 1, 0.3).Parent = frame
		Util.corner(props.Radius or 8).Parent = frame
	end

	return frame
end

-- Dropdown --------------------------------------------------------------------

--[[
	Provider-selector style dropdown.

	props = {
		Options  = { { id = "OpenAI", label = "OpenAI" }, ... },
		Value    = "OpenAI",
		OnSelect = function(id),
		Size, Parent, LayoutOrder, Placeholder
	}

	Returns the container Frame with two attached methods:
		container:SetValue(id)  container:GetValue()
]]
function Components.dropdown(props)
	props = props or {}

	local options = props.Options or {}
	local value = props.Value

	local function labelFor(id)
		for _, option in ipairs(options) do
			if option.id == id then
				return option.label or option.id
			end
		end
		return props.Placeholder or "Select..."
	end

	local container = Util.create("Frame", {
		Name = props.Name or "Dropdown",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = props.Size or UDim2.new(1, 0, 0, 36),
		Position = props.Position,
		LayoutOrder = props.LayoutOrder,
		ClipsDescendants = false,
		ZIndex = props.ZIndex or 2,
		Parent = props.Parent,
	})

	local toggle
	toggle = Components.button({
		Name = "Toggle",
		Text = "  " .. labelFor(value),
		Variant = "dark",
		Size = UDim2.new(1, 0, 1, 0),
		Radius = 8,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = container,
	})

	local arrow = Fonts.new("TextLabel", "small", {
		Name = "Arrow",
		BackgroundTransparency = 1,
		Text = "v",
		TextColor3 = Palette.text.secondary,
		Size = UDim2.new(0, 16, 1, 0),
		Position = UDim2.new(1, -14, 0, 0),
		AnchorPoint = Vector2.new(1, 0),
		TextXAlignment = Enum.TextXAlignment.Center,
		TextYAlignment = Enum.TextYAlignment.Center,
		ZIndex = 3,
		Parent = toggle,
	})

	local list = Util.create("Frame", {
		Name = "List",
		BackgroundColor3 = Palette.surfaces.card,
		BorderSizePixel = 0,
		Visible = false,
		Size = UDim2.new(1, 0, 0, #options * 30 + 8),
		Position = UDim2.new(0, 0, 1, 4),
		ZIndex = 60,
		Parent = container,
	}, {
		Util.corner(8),
		Util.stroke(Palette.surfaces.border, 1, 0.1),
		Util.padding(4),
		Util.list({ Padding = UDim.new(0, 2) }),
	})

	local rows = {}

	local function close()
		list.Visible = false
		arrow.Text = "v"
	end

	local function open()
		list.Visible = true
		arrow.Text = "^"
	end

	-- `programmatic` suppresses OnSelect so callers can sync the widget from
	-- state without re-entering their own change handler.
	local function select(id, programmatic)
		value = id
		toggle.Text = "  " .. labelFor(id)
		for _, row in ipairs(rows) do
			row.TextColor3 = (row:GetAttribute("optionId") == id) and Palette.neon.green or Palette.text.primary
		end
		close()

		if props.OnSelect and not programmatic then
			props.OnSelect(id)
		end
	end

	for index, option in ipairs(options) do
		local row = Fonts.new("TextButton", "body", {
			Name = "Option" .. tostring(index),
			Text = option.label or option.id,
			TextColor3 = option.id == value and Palette.neon.green or Palette.text.primary,
			BackgroundColor3 = Palette.surfaces.card,
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			BorderSizePixel = 0,
			TextXAlignment = Enum.TextXAlignment.Left,
			Size = UDim2.new(1, 0, 0, 28),
			LayoutOrder = index,
			ZIndex = 61,
			Parent = list,
		})

		row:SetAttribute("optionId", option.id)

		row.MouseEnter:Connect(function()
			Util.animate(row, { BackgroundTransparency = 0.4, BackgroundColor3 = Palette.surfaces.border }, 0.12)
		end)
		row.MouseLeave:Connect(function()
			Util.animate(row, { BackgroundTransparency = 1 }, 0.12)
		end)
		row.MouseButton1Click:Connect(function()
			select(option.id)
		end)

		table.insert(rows, row)
	end

	toggle.MouseButton1Click:Connect(function()
		if list.Visible then
			close()
		else
			open()
		end
	end)

	--- Programmatic value sync; does not fire OnSelect.
	function container:SetValue(id)
		select(id, true)
	end

	function container:GetValue()
		return value
	end

	container.Toggle = toggle
	container.List = list

	return container
end

-- Tabs ------------------------------------------------------------------------

--[[
	props = { Items = { { id, label } }, Value, OnSelect, Parent, Size, LayoutOrder }

	Returns the container Frame with container:SetActive(id).
]]
function Components.tabs(props)
	props = props or {}

	local container = Util.create("Frame", {
		Name = props.Name or "Tabs",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = props.Size or UDim2.new(1, 0, 0, 34),
		LayoutOrder = props.LayoutOrder,
		Parent = props.Parent,
	}, {
		Util.list({
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 6),
			VerticalAlignment = Enum.VerticalAlignment.Center,
		}),
	})

	local buttons = {}
	local active = props.Value

	local function apply(id)
		for _, entry in ipairs(buttons) do
			local isActive = entry.id == id
			entry.button.BackgroundColor3 = isActive and Palette.states.green.idle or Palette.surfaces.card
			entry.button.TextColor3 = isActive and Palette.text.inverse or Palette.text.secondary
			entry.marker.Visible = isActive
			local stroke = entry.button:FindFirstChildOfClass("UIStroke")
			if stroke then
				stroke.Color = isActive and Palette.neon.green or Palette.surfaces.border
				stroke.Transparency = isActive and 0.1 or 0.45
			end
		end
	end

	for index, item in ipairs(props.Items or {}) do
		local button = Components.button({
			Name = "Tab" .. tostring(index),
			Text = item.label or item.id,
			Variant = "dark",
			Size = UDim2.new(0, 96, 1, 0),
			LayoutOrder = index,
			Parent = container,
			OnClick = function()
				active = item.id
				apply(item.id)
				if props.OnSelect then
					props.OnSelect(item.id)
				end
			end,
		})

		local marker = Util.create("Frame", {
			Name = "Marker",
			BackgroundColor3 = Palette.neon.green,
			BorderSizePixel = 0,
			Size = UDim2.new(1, -16, 0, 2),
			Position = UDim2.new(0, 8, 1, -2),
			Visible = false,
			ZIndex = 4,
			Parent = button,
		})

		table.insert(buttons, { id = item.id, button = button, marker = marker })
	end

	function container:SetActive(id)
		active = id
		apply(id)
	end

	function container:GetActive()
		return active
	end

	apply(active)

	return container
end

-- Small helpers ---------------------------------------------------------------

--- Coloured status dot used by the connection indicators.
function Components.dot(props)
	props = props or {}
	return Util.create("Frame", {
		Name = "Dot",
		BackgroundColor3 = props.Color or Palette.neon.green,
		BorderSizePixel = 0,
		Size = UDim2.new(0, props.Size or 8, 0, props.Size or 8),
		Position = props.Position,
		AnchorPoint = Vector2.new(0.5, 0.5),
		LayoutOrder = props.LayoutOrder,
		Parent = props.Parent,
	}, {
		Util.corner(999),
	})
end

--- Multi-line read-only output console for the Code / Cowork panes.
function Components.console(props)
	props = props or {}

	local frame = Util.create("Frame", {
		Name = props.Name or "Console",
		BackgroundColor3 = Palette.surfaces.background,
		BorderSizePixel = 0,
		Size = props.Size or UDim2.new(1, 0, 1, 0),
		Position = props.Position,
		LayoutOrder = props.LayoutOrder,
		Parent = props.Parent,
	}, {
		Util.corner(8),
		Util.stroke(Palette.surfaces.border, 1, 0.2),
	})

	local scroll = Components.scroll({
		Size = UDim2.new(1, -12, 1, -12),
		Position = UDim2.new(0, 6, 0, 6),
		Padding = 2,
		Inset = 2,
		Parent = frame,
	})

	frame.Scroll = scroll
	frame.Lines = {}

	local paletteText = {
		ok = Palette.neon.green,
		error = Palette.neon.pink,
		warn = Palette.characters.Morty.text,
		user = Palette.neon.cyan,
		info = Palette.text.secondary,
	}

	--- Appends a line; `kind` picks the colour scheme.
	function frame:Append(text, kind)
		local color = paletteText[kind or "info"] or Palette.text.primary

		local line = Fonts.new("TextLabel", "log", {
			Name = "Line",
			Text = text,
			TextColor3 = color,
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			TextWrapped = true,
			LayoutOrder = #self.Lines + 1,
			Parent = self.Scroll,
		})

		table.insert(self.Lines, line)
		task.defer(function()
			if self.Scroll then
				self.Scroll.CanvasPosition = Vector2.new(0, math.max(0, self.Scroll.AbsoluteCanvasSize.Y))
			end
		end)

		return line
	end

	function frame:Clear()
		Util.clear(self.Scroll)
		self.Lines = {}
	end

	return frame
end

return Components
end

__modules["ui/CoworkPanel"] = function(require)
--[[
	ui/CoworkPanel.lua
	Cowork mode: drops the local bridge into the executor's workspace folder and
	tells the user how to launch the external interface
	(idea/backend.md §2, idea/ui-creation.md §3).
]]

local Components = require("ui/Components")
local Cowork = require("core/Cowork")
local Fonts = require("core/Fonts")
local Notify = require("ui/Notify")
local Palette = require("core/Palette")
local Providers = require("core/Providers")
local State = require("core/State")
local Util = require("core/Util")

local CoworkPanel = {}

function CoworkPanel.new(parent, app)
	local frame = Util.create("Frame", {
		Name = "CoworkPanel",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, 0),
		Parent = parent,
	})

	local title = Fonts.new("TextLabel", "subtitle", {
		Name = "Title",
		Text = "Cowork bridge",
		TextColor3 = Palette.text.primary,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -24, 0, 22),
		Position = UDim2.new(0, 12, 0, 10),
		Parent = frame,
	})

	local blurb = Fonts.new("TextLabel", "small", {
		Name = "Blurb",
		Text = "Generates a local Node bridge in your executor workspace. Launching it opens the "
			.. "full-sized interface at "
			.. Cowork.URL
			.. ", where requests go straight to the provider without Roblox's HTTP whitelist.",
		TextColor3 = Palette.text.secondary,
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, -24, 0, 0),
		Position = UDim2.new(0, 12, 0, 34),
		TextWrapped = true,
		Parent = frame,
	})

	-- Info card ---------------------------------------------------------------

	local info = Components.panel({
		Name = "Info",
		Size = UDim2.new(1, -24, 0, 74),
		Position = UDim2.new(0, 12, 0, 92),
		Parent = frame,
	}, {
		Util.padding(10, 12, 10, 12),
		Util.list({ Padding = UDim.new(0, 4) }),
	})

	local function infoLine(order, text)
		return Fonts.new("TextLabel", "log", {
			Name = "Info" .. tostring(order),
			Text = text,
			TextColor3 = Palette.text.secondary,
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 14),
			LayoutOrder = order,
			Parent = info,
		})
	end

	local dirLine = infoLine(1, "")
	local urlLine = infoLine(2, "")
	local providerLine = infoLine(3, "")
	local statusLine = infoLine(4, "")

	-- Actions -----------------------------------------------------------------

	local actionRow = Util.create("Frame", {
		Name = "Actions",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -24, 0, 34),
		Position = UDim2.new(0, 12, 0, 178),
		Parent = frame,
	}, {
		Util.list({
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 8),
			VerticalAlignment = Enum.VerticalAlignment.Center,
		}),
	})

	local console = Components.console({
		Name = "Console",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 12, 1, -12),
		Size = UDim2.new(1, -24, 1, -228),
		Parent = frame,
	})

	local panel = {
		frame = frame,
		console = console,
	}

	function panel:refresh()
		local provider = Providers.get(State.provider())

		dirLine.Text = "folder   : " .. Cowork.DIR .. "/"
		urlLine.Text = "interface: " .. Cowork.URL .. "   (node 18+ required)"
		providerLine.Text = "provider : " .. State.provider() .. " // " .. tostring(State.model(provider.model))
		statusLine.Text = "status   : " .. Cowork.status() .. "   transport: " .. (Cowork.available() and "writefile ok" or "unavailable")
		statusLine.TextColor3 = Cowork.available() and Palette.neon.green or Palette.neon.pink
	end

	function panel:log(text, kind)
		console:Append(text, kind)
	end

	function panel:generate()
		panel:log("> writing " .. Cowork.DIR .. "/ ...", "info")

		local ok, result = Cowork.build()
		if not ok then
			panel:log("[error] " .. tostring(result), "error")
			if app and app.notify then
				app.notify("Cowork bridge failed", tostring(result))
			end
			panel:refresh()
			return
		end

		for _, path in ipairs(result) do
			panel:log("  wrote " .. tostring(path), "ok")
		end

		panel:log("done. double-click " .. Cowork.launchers.windows .. " (or run " .. Cowork.launchers.posix .. ") inside that folder.", "ok")
		panel:refresh()

		Notify.coworkInstructions(result)
	end

	Components.button({
		Name = "Generate",
		Text = "Generate bridge",
		Variant = "green",
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 1,
		Parent = actionRow,
		OnClick = function()
			panel:generate()
		end,
	})

	Components.button({
		Name = "Status",
		Text = "Re-check status",
		Variant = "dark",
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 2,
		Parent = actionRow,
		OnClick = function()
			panel:refresh()
			panel:log("[status] " .. Cowork.status(), "info")
		end,
	})

	Components.button({
		Name = "CopyUrl",
		Text = "Copy URL",
		Variant = "dark",
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 3,
		Parent = actionRow,
		OnClick = function()
			local setclipboard = Util.global("setclipboard")
			if type(setclipboard) == "function" then
				pcall(setclipboard, Cowork.URL)
				panel:log("[clipboard] " .. Cowork.URL, "ok")
			else
				panel:log("[clipboard] unavailable - open " .. Cowork.URL .. " manually", "warn")
			end
		end,
	})

	panel:refresh()
	panel:log("cowork ready. press 'Generate bridge' to write the local files.", "info")

	return panel
end

return CoworkPanel
end

__modules["ui/Dashboard"] = function(require)
--[[
	ui/Dashboard.lua
	The full-sized main menu from idea/main.md §1 and idea/ui-creation.md §1.

	  * no screen dimming - the console floats over the live viewport
	  * header: title.png anchored top-center with a locked aspect ratio
	  * left: persistent navigation sidebar (provider, companion, history)
	  * center: Chat / Cowork / Code workspace
	  * lower-right: the active companion frame
	  * plus a floating anchor button that reopens the window once it is hidden
]]

local Assets = require("core/Assets")
local ChatPanel = require("ui/ChatPanel")
local CodePanel = require("ui/CodePanel")
local Companion = require("ui/Companion")
local Components = require("ui/Components")
local CoworkPanel = require("ui/CoworkPanel")
local Fonts = require("core/Fonts")
local Palette = require("core/Palette")
local Sidebar = require("ui/Sidebar")
local State = require("core/State")
local Util = require("core/Util")

local Dashboard = {}

Dashboard.HEADER_HEIGHT = 76
Dashboard.TABS = {
	{ id = "Chat", label = "Chat" },
	{ id = "Cowork", label = "Cowork" },
	{ id = "Code", label = "Code" },
}

function Dashboard.new(gui, app)
	-- Root (no dimming layer) --------------------------------------------------

	local root = Util.create("Frame", {
		Name = "DashboardRoot",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, 0),
		Visible = false,
		ZIndex = 100,
		Parent = gui,
	})

	local window = Util.create("Frame", {
		Name = "Window",
		BackgroundColor3 = Palette.surfaces.background,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -60, 1, -120),
		Position = UDim2.new(0.5, 0, 0.5, 0),
		AnchorPoint = Vector2.new(0.5, 0.5),
		ClipsDescendants = true,
		Parent = root,
	}, {
		Util.corner(12),
		Util.stroke(Palette.surfaces.border, 1, 0),
		Util.create("UISizeConstraint", {
			MinSize = Vector2.new(900, 560),
			MaxSize = Vector2.new(1180, 700),
		}),
	})

	-- Header ------------------------------------------------------------------

	local header = Util.create("Frame", {
		Name = "Header",
		BackgroundColor3 = Palette.surfaces.panel,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, Dashboard.HEADER_HEIGHT),
		Parent = window,
	})

	Util.create("Frame", {
		Name = "Seam",
		BackgroundColor3 = Palette.surfaces.border,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 1),
		Position = UDim2.new(0, 0, 1, -1),
		Parent = header,
	})

	local companionBadge = Components.badge({
		Name = "CompanionBadge",
		Text = string.upper(State.companion()),
		Position = UDim2.new(0, 16, 0.5, 0),
		AnchorPoint = Vector2.new(0, 0.5),
		Parent = header,
	})

	local providerBadge = Components.badge({
		Name = "ProviderBadge",
		Text = State.provider(),
		Color = Palette.neon.cyan,
		Position = UDim2.new(0, 16, 0.5, 26),
		AnchorPoint = Vector2.new(0, 0.5),
		Parent = header,
	})

	-- title.png anchored top-center, aspect locked to the trimmed logo ratio.
	local title = Assets.imageLabel("title", {
		Name = "Title",
		Size = UDim2.new(0, 300, 1, -16),
		Position = UDim2.new(0.5, 0, 0.5, 0),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Parent = header,
	})
	Assets.aspect(title, Assets.TITLE_ASPECT, Enum.DominantAxis.Height)

	local headerActions = Util.create("Frame", {
		Name = "Actions",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 260, 1, 0),
		Position = UDim2.new(1, -16, 0, 0),
		AnchorPoint = Vector2.new(1, 0),
		Parent = header,
	}, {
		Util.list({
			FillDirection = Enum.FillDirection.Horizontal,
			HorizontalAlignment = Enum.HorizontalAlignment.Right,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 6),
		}),
	})

	-- Body --------------------------------------------------------------------

	local body = Util.create("Frame", {
		Name = "Body",
		BackgroundColor3 = Palette.surfaces.background,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, -Dashboard.HEADER_HEIGHT),
		Position = UDim2.new(0, 0, 0, Dashboard.HEADER_HEIGHT),
		Parent = window,
	})

	local sidebar = Sidebar.new(body, app)
	app.sidebar = sidebar

	local main = Util.create("Frame", {
		Name = "Main",
		BackgroundColor3 = Palette.surfaces.background,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -Sidebar.WIDTH, 1, 0),
		Position = UDim2.new(0, Sidebar.WIDTH, 0, 0),
		ZIndex = 2,
		Parent = body,
	})

	local tabs = Components.tabs({
		Name = "WorkspaceTabs",
		Items = Dashboard.TABS,
		Value = "Chat",
		Size = UDim2.new(1, -24, 0, 34),
		Position = UDim2.new(0, 12, 0, 12),
		Parent = main,
		OnSelect = function(id)
			dashboard:setTab(id)
		end,
	})

	local content = Util.create("Frame", {
		Name = "Content",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, -58),
		Position = UDim2.new(0, 0, 0, 58),
		Parent = main,
	})

	local panels = {
		Chat = ChatPanel.new(content, app),
		Cowork = CoworkPanel.new(content, app),
		Code = CodePanel.new(content, app),
	}

	for _, panel in pairs(panels) do
		panel.frame.Visible = false
	end

	-- Companion ---------------------------------------------------------------

	local companion = Companion.create(window, {
		Name = State.companion(),
		Position = UDim2.new(1, -18, 1, -18),
		AnchorPoint = Vector2.new(1, 1),
		ZIndex = 5,
		Parent = window,
	})

	-- Anchor shortcut button (bottom-left) ------------------------------------

	local anchor = Util.create("Frame", {
		Name = "AnchorButton",
		BackgroundColor3 = Palette.surfaces.panel,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 132, 0, 42),
		Position = UDim2.new(0, 18, 1, -18),
		AnchorPoint = Vector2.new(0, 1),
		ZIndex = 120,
		Parent = gui,
	}, {
		Util.corner(10),
		Util.stroke(Palette.surfaces.border, 1, 0.2),
		Util.padding(6),
	})

	local anchorPortrait = Assets.imageLabel(string.lower(State.companion()), {
		Name = "Portrait",
		Image = Assets.portrait(State.companion()),
		Size = UDim2.new(0, 30, 1, 0),
		Parent = anchor,
	})

	Fonts.new("TextLabel", "small", {
		Name = "Label",
		Text = "AI CONSOLE",
		TextColor3 = Palette.text.primary,
		TextSize = 10,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -36, 1, 0),
		Position = UDim2.new(0, 36, 0, 0),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		Parent = anchor,
	})

	local anchorButton = Components.button({
		Name = "Hit",
		Text = "",
		Variant = "dark",
		Size = UDim2.new(1, 0, 1, 0),
		BackgroundTransparency = 1,
		ZIndex = 121,
		Parent = anchor,
		OnClick = function()
			root.Visible = true
			anchor.Visible = false
		end,
	})

	local anchorStroke = anchorButton:FindFirstChildOfClass("UIStroke")
	if anchorStroke then
		anchorStroke.Transparency = 1
	end

	-- Dragging ----------------------------------------------------------------

	local dragging = false
	local dragStart
	local startPosition

	--- True when a screen-space point sits inside a GuiObject.
	local function insideGui(instance, position)
		local topLeft = instance.AbsolutePosition
		local size = instance.AbsoluteSize

		return position.X >= topLeft.X
			and position.X <= topLeft.X + size.X
			and position.Y >= topLeft.Y
			and position.Y <= topLeft.Y + size.Y
	end

	header.InputBegan:Connect(function(inputObject)
		if inputObject.UserInputType == Enum.UserInputType.MouseButton1 then
			-- Let header buttons take their own clicks.
			if headerActions.Visible and insideGui(headerActions, inputObject.Position) then
				return
			end

			dragging = true
			dragStart = inputObject.Position
			startPosition = window.Position

			inputObject.Changed:Connect(function()
				if inputObject.UserInputState == Enum.UserInputState.End then
					dragging = false
				end
			end)
		end
	end)

	header.InputChanged:Connect(function(inputObject)
		if not dragging or inputObject.UserInputType ~= Enum.UserInputType.MouseMovement then
			return
		end

		local delta = inputObject.Position - dragStart
		window.Position = UDim2.new(
			startPosition.X.Scale,
			startPosition.X.Offset + delta.X,
			startPosition.Y.Scale,
			startPosition.Y.Offset + delta.Y
		)
	end)

	-- Header buttons ----------------------------------------------------------

	Components.button({
		Name = "QuickMenuButton",
		Text = "quick menu  ;",
		Variant = "dark",
		Size = UDim2.new(0, 0, 0, 34),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 1,
		Parent = headerActions,
		OnClick = function()
			if app.ToggleQuickMenu then
				app.ToggleQuickMenu()
			end
		end,
	})

	Components.button({
		Name = "NewChatButton",
		Text = "New chat",
		Variant = "dark",
		Size = UDim2.new(0, 0, 0, 34),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 2,
		Parent = headerActions,
		OnClick = function()
			State.resetHistory()
			panels.Chat:clear()
			sidebar:refreshSessions()
			dashboard:setTab("Chat")
		end,
	})

	Components.button({
		Name = "HideButton",
		Text = "Hide",
		Variant = "dark",
		Size = UDim2.new(0, 0, 0, 34),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 3,
		Parent = headerActions,
		OnClick = function()
			dashboard:setVisible(false)
		end,
	})

	Components.button({
		Name = "UnloadButton",
		Text = "Unload",
		Variant = "pink",
		Size = UDim2.new(0, 0, 0, 34),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 4,
		Parent = headerActions,
		OnClick = function()
			if app.Unload then
				app.Unload()
			end
		end,
	})

	-- API ---------------------------------------------------------------------

	local dashboard = {
		root = root,
		window = window,
		header = header,
		body = body,
		main = main,
		tabs = tabs,
		panels = panels,
		companion = companion,
		anchor = anchor,
	}

	function dashboard:setVisible(visible)
		root.Visible = visible == true
		anchor.Visible = not root.Visible
	end

	function dashboard:isVisible()
		return root.Visible
	end

	function dashboard:toggle()
		dashboard:setVisible(not root.Visible)
	end

	function dashboard:setTab(id)
		local resolved = panels[id] and id or "Chat"

		for panelId, panel in pairs(panels) do
			panel.frame.Visible = panelId == resolved
		end

		tabs:SetActive(resolved)
		self.activeTab = resolved

		local panel = panels[resolved]
		if panel.render and resolved == "Chat" then
			panel:render()
		end
		if panel.refresh then
			panel:refresh()
		end
	end

	--- Appends a line to the Code pane's console (shared log target).
	function dashboard:log(text, kind)
		panels.Code:log(text, kind)
	end

	function dashboard:loadCode(source)
		panels.Code:setSource(source)
	end

	function dashboard:refresh()
		companionBadge.TextLabel.Text = string.upper(State.companion())
		providerBadge.TextLabel.Text = State.provider()
		companion:SetCharacter(State.companion())
		anchorPortrait.Image = Assets.portrait(State.companion())
		sidebar:refresh()
		panels.Chat:refresh()
	end

	function dashboard:destroy()
		anchor:Destroy()
		root:Destroy()
	end

	dashboard:setTab("Chat")
	dashboard:setVisible(false)

	return dashboard
end

return Dashboard
end

__modules["ui/Notify"] = function(require)
--[[
	ui/Notify.lua
	Toasts for errors, execution results and the Cowork "double-click the bridge
	file" instructions (idea/backend.md §2 step 4).

	Layout note: the accent rail is parented to the wrap, not the card, because
	the card runs a UIListLayout and every visible GuiObject inside it would
	otherwise be given a slot.
]]

local Assets = require("core/Assets")
local Components = require("ui/Components")
local Cowork = require("core/Cowork")
local Fonts = require("core/Fonts")
local Palette = require("core/Palette")
local State = require("core/State")
local Util = require("core/Util")

local Notify = {}

Notify.container = nil
Notify.history = {}

local VARIANT_COLORS = {
	info = Palette.neon.cyan,
	ok = Palette.neon.green,
	warn = Palette.characters.Morty.text,
	error = Palette.neon.pink,
}

function Notify.setup(gui)
	if Notify.container and Notify.container.Parent then
		return Notify.container
	end

	Notify.container = Util.create("Frame", {
		Name = "Notifications",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 360, 0, 0),
		Position = UDim2.new(1, -18, 0, 18),
		AnchorPoint = Vector2.new(1, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		ZIndex = 200,
		Parent = gui,
	}, {
		Util.list({
			Padding = UDim.new(0, 10),
			HorizontalAlignment = Enum.HorizontalAlignment.Right,
			VerticalAlignment = Enum.VerticalAlignment.Top,
		}),
	})

	return Notify.container
end

--[[
	options = {
		Title, Body, Variant ("info"|"ok"|"warn"|"error"),
		Duration (seconds, 0 = sticky), Portrait (companion name or false),
		Actions = { { label = string, Variant = string, OnClick = function } }
	}

	Returns (wrap, dismiss).
]]
function Notify.toast(options)
	options = options or {}

	local container = options.Parent or Notify.container
	if not container or not container.Parent then
		warn("[RickMortyAI] " .. tostring(options.Title or "") .. ": " .. tostring(options.Body or ""))
		return nil
	end

	local accent = VARIANT_COLORS[options.Variant or "info"] or Palette.neon.cyan

	local wrap = Components.panel({
		Name = "Toast",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = Palette.surfaces.panel,
		Parent = container,
	})

	local stroke = wrap:FindFirstChildOfClass("UIStroke")
	if stroke then
		stroke.Color = accent
		stroke.Transparency = 0.55
	end

	local rail = Util.create("Frame", {
		Name = "Rail",
		BackgroundColor3 = accent,
		BorderSizePixel = 0,
		-- Offset height only: a scale-height child under an AutomaticSize parent
		-- makes the layout circular, so it is driven from the card instead.
		Size = UDim2.new(0, 3, 0, 0),
		Position = UDim2.new(0, 0, 0, 6),
		ZIndex = 2,
		Parent = wrap,
	}, { Util.corner(2) })

	local card = Util.create("Frame", {
		Name = "Card",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -10, 0, 0),
		Position = UDim2.new(0, 10, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = wrap,
	}, {
		Util.padding(12, 12, 12, 10),
		Util.list({ Padding = UDim.new(0, 8) }),
	})

	card:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		rail.Size = UDim2.new(0, 3, 0, math.max(0, card.AbsoluteSize.Y - 12))
	end)

	local scale = Util.create("UIScale", { Scale = 0.94, Parent = wrap })

	local header = Util.create("Frame", {
		Name = "Header",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 18),
		LayoutOrder = 1,
		Parent = card,
	})

	Fonts.new("TextLabel", "subtitle", {
		Name = "Title",
		Text = options.Title or "Notice",
		TextColor3 = accent,
		TextSize = 14,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -30, 1, 0),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		Parent = header,
	})

	local close = Components.button({
		Name = "Close",
		Text = "x",
		Variant = "dark",
		Size = UDim2.new(0, 24, 0, 18),
		Position = UDim2.new(1, 0, 0, 0),
		AnchorPoint = Vector2.new(1, 0),
		Radius = 6,
		Parent = header,
	})

	local content = Util.create("Frame", {
		Name = "Content",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Parent = card,
	})

	local textInset = 0

	if options.Portrait ~= false then
		local portraitName = options.Portrait or State.companion()
		textInset = 46

		Util.create("ImageLabel", {
			Name = "Portrait",
			BackgroundTransparency = 1,
			Image = Assets.portrait(portraitName),
			ScaleType = Enum.ScaleType.Fit,
			Size = UDim2.new(0, 40, 0, 40),
			Position = UDim2.new(0, 0, 0, 0),
			ZIndex = 3,
			Parent = content,
		})
	end

	Fonts.new("TextLabel", "body", {
		Name = "Body",
		Text = options.Body or "",
		TextColor3 = Palette.text.primary,
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, -textInset, 0, 0),
		Position = UDim2.new(0, textInset, 0, 0),
		TextWrapped = true,
		Parent = content,
	})

	if options.Actions and #options.Actions > 0 then
		local actions = Util.create("Frame", {
			Name = "Actions",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 0, 30),
			LayoutOrder = 3,
			Parent = card,
		}, {
			Util.list({
				FillDirection = Enum.FillDirection.Horizontal,
				Padding = UDim.new(0, 6),
				VerticalAlignment = Enum.VerticalAlignment.Center,
			}),
		})

		for index, action in ipairs(options.Actions) do
			Components.button({
				Name = "Action" .. tostring(index),
				Text = action.label,
				Variant = action.Variant or "dark",
				Size = UDim2.new(0, 0, 1, 0),
				AutomaticSize = Enum.AutomaticSize.X,
				LayoutOrder = index,
				Parent = actions,
				OnClick = function()
					if action.OnClick then
						action.OnClick()
					end
				end,
			})
		end
	end

	-- Fade + pop in (position is owned by the container's list layout).
	wrap.BackgroundTransparency = 1
	Util.animate(wrap, { BackgroundTransparency = 0 }, 0.2)
	Util.animate(scale, { Scale = 1 }, 0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out)

	local dismissed = false
	local function dismiss()
		if dismissed then
			return
		end
		dismissed = true

		Util.animate(scale, { Scale = 0.94 }, 0.15)
		local tween = Util.animate(wrap, { BackgroundTransparency = 1 }, 0.16)
		tween.Completed:Connect(function()
			wrap:Destroy()
		end)
	end

	close.MouseButton1Click:Connect(dismiss)

	local duration = options.Duration == nil and 6 or options.Duration
	if duration > 0 then
		task.delay(duration, dismiss)
	end

	table.insert(Notify.history, { title = options.Title, body = options.Body })

	return wrap, dismiss
end

--- Cowork instruction toast with the portrait pointing at the launcher.
function Notify.coworkInstructions(files)
	local list = files and table.concat(files, "\n") or ""

	return Notify.toast({
		Title = "Cowork bridge generated",
		Variant = "ok",
		Duration = 0,
		Body = Cowork.instructions() .. (list ~= "" and ("\n\nWritten:\n" .. list) or ""),
		Actions = {
			{ label = "Got it", Variant = "dark" },
		},
	})
end

function Notify.info(title, body)
	return Notify.toast({ Title = title, Body = body, Variant = "info" })
end

function Notify.error(title, body)
	return Notify.toast({ Title = title, Body = body, Variant = "error", Duration = 9 })
end

return Notify
end

__modules["ui/QuickMenu"] = function(require)
--[[
	ui/QuickMenu.lua
	The semicolon quick-menu from idea/main.md §1 and idea/backend.md §4.

	  * pressing ';' spawns a full-screen overlay over the game canvas
	    (BackgroundColor3 #0D1117, BackgroundTransparency 0.4)
	  * movement keys are sunk while it is open so the character does not walk
	  * submitting a prompt sends it straight to the active provider, extracts the
	    ```lua block, executes it into the live workspace, then closes
	  * Escape or a click on the dim backdrop closes it
]]

local Assets = require("core/Assets")
local Chat = require("core/Chat")
local Companion = require("ui/Companion")
local Components = require("ui/Components")
local Fonts = require("core/Fonts")
local Palette = require("core/Palette")
local State = require("core/State")
local Util = require("core/Util")

local QuickMenu = {}

QuickMenu.WIDTH = 640
QuickMenu.HEIGHT = 340

local SINK_ACTION = "RickMortyAI_QuickMenuSink"
local SINK_KEYS = {
	Enum.KeyCode.W,
	Enum.KeyCode.A,
	Enum.KeyCode.S,
	Enum.KeyCode.D,
	Enum.KeyCode.Q,
	Enum.KeyCode.E,
	Enum.KeyCode.Space,
	Enum.KeyCode.LeftShift,
	Enum.KeyCode.LeftControl,
}

function QuickMenu.new(gui, app)
	local UserInputService = game:GetService("UserInputService")
	local ContextActionService = game:GetService("ContextActionService")

	local self = {
		isOpen = false,
		busy = false,
	}

	local connections = Util.connections()

	-- Backdrop -----------------------------------------------------------------

	local overlay = Util.create("Frame", {
		Name = "QuickMenu",
		BackgroundColor3 = Palette.overlay.color,
		BackgroundTransparency = Palette.overlay.transparency,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, 0),
		Visible = false,
		ZIndex = 250,
		Parent = gui,
	})

	-- Centered module ----------------------------------------------------------

	local module = Components.panel({
		Name = "Module",
		BackgroundColor3 = Palette.surfaces.background,
		Size = UDim2.new(0, QuickMenu.WIDTH, 0, QuickMenu.HEIGHT),
		Position = UDim2.new(0.5, 0, 0.5, 0),
		AnchorPoint = Vector2.new(0.5, 0.5),
		ZIndex = 251,
		Parent = overlay,
	}, {
		Util.padding(18),
	})

	-- title.png at 50% of the module width, aspect locked to the logo's trim.
	local title = Assets.imageLabel("title", {
		Name = "Title",
		Size = UDim2.new(0.5, 0, 0, 84),
		Position = UDim2.new(0.5, 0, 0, 0),
		AnchorPoint = Vector2.new(0.5, 0),
		ZIndex = 252,
		Parent = module,
	})
	Assets.aspect(title, Assets.TITLE_ASPECT, Enum.DominantAxis.Height)

	local input = Components.input({
		Name = "Prompt",
		Placeholder = "portal gun, but for luau...",
		Size = UDim2.new(1, 0, 0, 46),
		Position = UDim2.new(0, 0, 0, 104),
		ZIndex = 253,
		Parent = module,
		OnSubmit = function(text, enterPressed)
			if enterPressed then
				self:submit(text)
			end
		end,
	})

	local status = Fonts.new("TextLabel", "small", {
		Name = "Status",
		Text = "type a prompt, hit enter, the script runs itself",
		TextColor3 = Palette.text.secondary,
		TextSize = 11,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 18),
		Position = UDim2.new(0, 0, 0, 158),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		ZIndex = 253,
		Parent = module,
	})

	local companionHolder = Util.create("Frame", {
		Name = "CompanionHolder",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 64, 0, 64),
		Position = UDim2.new(0, 0, 0, 190),
		ZIndex = 253,
		Parent = module,
	})

	local providerBadge = Components.badge({
		Name = "ProviderBadge",
		Text = State.provider(),
		Color = Palette.neon.cyan,
		Position = UDim2.new(1, 0, 0, 196),
		AnchorPoint = Vector2.new(1, 0),
		ZIndex = 253,
		Parent = module,
	})

	Fonts.new("TextLabel", "small", {
		Name = "Hint",
		Text = "esc closes  |  output executes into workspace and is mirrored in the Code tab",
		TextColor3 = Palette.text.dim,
		TextSize = 10,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 18),
		Position = UDim2.new(0, 0, 1, -18),
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = 253,
		Parent = module,
	})

	-- Companion portrait ------------------------------------------------------

	local portrait

	local function mountPortrait()
		if portrait then
			portrait:Destroy()
		end

		portrait = Companion.create(companionHolder, {
			Name = State.companion(),
			Size = 64,
			Position = UDim2.new(0, 0, 0, 0),
			AnchorPoint = Vector2.new(0, 0),
			ZIndex = 254,
			Parent = companionHolder,
		})
	end

	-- Behaviour ---------------------------------------------------------------

	local function sinkMovement(enabled)
		if enabled then
			ContextActionService:BindAction(SINK_ACTION, function()
				return Enum.ContextActionResult.Sink
			end, false, table.unpack(SINK_KEYS))
		else
			pcall(function()
				ContextActionService:UnbindAction(SINK_ACTION)
			end)
		end
	end

	function self:open()
		if self.isOpen then
			return
		end

		self.isOpen = true
		mountPortrait()
		providerBadge.TextLabel.Text = State.provider()
		overlay.Visible = true
		sinkMovement(true)

		task.defer(function()
			input:CaptureFocus()
		end)
	end

	function self:close()
		if not self.isOpen then
			return
		end

		self.isOpen = false
		overlay.Visible = false
		pcall(function()
			input:ReleaseFocus()
		end)
		sinkMovement(false)
	end

	function self:toggle()
		if self.isOpen then
			self:close()
		else
			self:open()
		end
	end

	function self:setStatus(text, kind)
		status.Text = text
		status.TextColor3 = kind == "error" and Palette.neon.pink
			or kind == "ok" and Palette.neon.green
			or Palette.text.secondary
	end

	--- Dispatch + execute + close (main.md §1 workflow loop).
	function self:submit(text)
		local prompt = Util.trim(text or input.Text)
		if prompt == "" or self.busy then
			return
		end

		self.busy = true
		input.Text = ""
		self:setStatus("dispatching to " .. State.provider() .. "...")

		Chat.sendAndRun(prompt, function(line, kind)
			if app and app.dashboard then
				app.dashboard:log(line, kind)
			end
		end, {
			onExecuted = function(ok, output)
				self:setStatus(
					ok and ("executed: " .. Util.truncate(tostring(output), 64)) or ("failed: " .. tostring(output)),
					ok and "ok" or "error"
				)
			end,
			onError = function(message)
				self:setStatus(tostring(message), "error")
			end,
			onFinish = function()
				self.busy = false
				if self.isOpen then
					task.delay(0.6, function()
						if not self.busy and self.isOpen then
							self:close()
						end
					end)
				end
			end,
		})
	end

	--- True when a screen-space point sits inside the module.
	local function insideModule(position)
		local topLeft = module.AbsolutePosition
		local size = module.AbsoluteSize

		return position.X >= topLeft.X
			and position.X <= topLeft.X + size.X
			and position.Y >= topLeft.Y
			and position.Y <= topLeft.Y + size.Y
	end

	-- Input -------------------------------------------------------------------

	connections.add(UserInputService.InputBegan, function(inputObject, processed)
		if inputObject.KeyCode == Enum.KeyCode.Semicolon and not processed then
			self:toggle()
		elseif inputObject.KeyCode == Enum.KeyCode.Escape and self.isOpen then
			self:close()
		end
	end)

	-- Clicking the dim backdrop (outside the module) closes.
	connections.add(overlay.InputBegan, function(inputObject)
		local isClick = inputObject.UserInputType == Enum.UserInputType.MouseButton1
			or inputObject.UserInputType == Enum.UserInputType.Touch

		if isClick and not insideModule(inputObject.Position) then
			self:close()
		end
	end)

	function self:destroy()
		self:close()
		connections.destroy()
		sinkMovement(false)
		if overlay then
			overlay:Destroy()
		end
	end

	self.overlay = overlay
	self.module = module
	self.input = input
	self.title = title

	return self
end

return QuickMenu
end

__modules["ui/Sidebar"] = function(require)
--[[
	ui/Sidebar.lua
	Persistent navigation rail from idea/ui-creation.md §1:
	  * provider selector (dropdown, preset templates)
	  * companion switch (Rick / Morty)
	  * settings: API key, model override, transport status
	  * chat history (archived sessions)
	  * footer: stats + unload
]]

local Components = require("ui/Components")
local Fonts = require("core/Fonts")
local Http = require("core/Http")
local Palette = require("core/Palette")
local Providers = require("core/Providers")
local State = require("core/State")
local Util = require("core/Util")

local Sidebar = {}

Sidebar.WIDTH = 252

local function heading(parent, text, order)
	local label = Fonts.new("TextLabel", "small", {
		Name = "Heading",
		Text = string.upper(text),
		TextColor3 = Palette.text.dim,
		TextSize = 10,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 16),
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = order,
		Parent = parent,
	})

	label.TextSize = 10
	return label
end

function Sidebar.new(parent, app)
	local frame = Util.create("Frame", {
		Name = "Sidebar",
		BackgroundColor3 = Palette.surfaces.panel,
		BorderSizePixel = 0,
		Size = UDim2.new(0, Sidebar.WIDTH, 1, 0),
		ZIndex = 3,
		Parent = parent,
	})

	Util.create("Frame", {
		Name = "Edge",
		BackgroundColor3 = Palette.surfaces.border,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 1, 1, 0),
		Position = UDim2.new(1, -1, 0, 0),
		Parent = frame,
	})

	local stack = Util.create("Frame", {
		Name = "Stack",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -24, 1, -24),
		Position = UDim2.new(0, 12, 0, 12),
		Parent = frame,
	}, {
		Util.list({ Padding = UDim.new(0, 8) }),
	})

	-- Provider -----------------------------------------------------------------

	heading(stack, "AI provider", 1)

	local providerDropdown = Components.dropdown({
		Name = "ProviderDropdown",
		Options = (function()
			local options = {}
			for _, id in ipairs(Providers.ids()) do
				table.insert(options, { id = id, label = id })
			end
			return options
		end)(),
		Value = State.provider(),
		Size = UDim2.new(1, 0, 0, 34),
		LayoutOrder = 2,
		Parent = stack,
		OnSelect = function(id)
			State.setProvider(id)
			Sidebar.refresh(app)
		end,
	})

	local providerHint = Fonts.new("TextLabel", "small", {
		Name = "ProviderHint",
		Text = Providers.get(State.provider()).description,
		TextColor3 = Palette.text.secondary,
		TextSize = 11,
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, 0, 0, 0),
		TextWrapped = true,
		LayoutOrder = 3,
		Parent = stack,
	})

	-- Companion ----------------------------------------------------------------

	heading(stack, "Companion", 4)

	local companionRow = Util.create("Frame", {
		Name = "CompanionRow",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 32),
		LayoutOrder = 5,
		Parent = stack,
	}, {
		Util.list({
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 6),
			VerticalAlignment = Enum.VerticalAlignment.Center,
		}),
	})

	local companionButtons = {}

	for index, name in ipairs(Palette.characterOrder) do
		local theme = Palette.character(name)

		local button = Components.button({
			Name = name .. "Button",
			Text = name,
			Variant = "dark",
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			LayoutOrder = index,
			Parent = companionRow,
			TextColor3 = theme.text,
			OnClick = function()
				State.setCompanion(name)
				if app and app.OnCompanionChanged then
					app.OnCompanionChanged(name)
				end
				Sidebar.refresh(app)
			end,
		})

		companionButtons[name] = button
	end

	-- Settings -----------------------------------------------------------------

	heading(stack, "Settings", 6)

	local keyInput = Components.input({
		Name = "KeyInput",
		Text = State.apiKey(State.provider()),
		Placeholder = Providers.get(State.provider()).keyLabel,
		Size = UDim2.new(1, 0, 0, 30),
		LayoutOrder = 7,
		Parent = stack,
		OnSubmit = function(text)
			State.setApiKey(Util.trim(text))
			Sidebar.refresh(app)
		end,
	})

	local modelInput = Components.input({
		Name = "ModelInput",
		Text = State.model(Providers.get(State.provider()).model),
		Placeholder = "model id",
		Size = UDim2.new(1, 0, 0, 30),
		LayoutOrder = 8,
		Parent = stack,
		OnSubmit = function(text)
			State.setModel(Util.trim(text))
		end,
	})

	local saveButton = Components.button({
		Name = "SaveSettings",
		Text = "Save credentials",
		Variant = "green",
		Size = UDim2.new(1, 0, 0, 28),
		LayoutOrder = 9,
		Parent = stack,
		OnClick = function()
			State.setApiKey(Util.trim(keyInput.Text))
			State.setModel(Util.trim(modelInput.Text))
			State.save()
			if app and app.notify then
				app.notify("Credentials saved", State.provider() .. " // " .. State.model("default"))
			end
		end,
	})

	local transport = Fonts.new("TextLabel", "small", {
		Name = "Transport",
		Text = "transport: " .. Http.transportName(),
		TextColor3 = Http.available() and Palette.text.dim or Palette.neon.pink,
		TextSize = 10,
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, 0, 0, 0),
		TextWrapped = true,
		LayoutOrder = 10,
		Parent = stack,
	})

	-- History ------------------------------------------------------------------

	heading(stack, "Chat history", 11)

	local sessions = Components.scroll({
		Name = "Sessions",
		Size = UDim2.new(1, 0, 0, 150),
		LayoutOrder = 12,
		Padding = 4,
		Inset = 0,
		Parent = stack,
	})

	-- Footer -------------------------------------------------------------------

	-- Vertical stack: full-width children only, so nothing can overflow the rail.
	local footer = Util.create("Frame", {
		Name = "Footer",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 46),
		LayoutOrder = 13,
		Parent = stack,
	}, {
		Util.list({ Padding = UDim.new(0, 4) }),
	})

	Fonts.new("TextLabel", "small", {
		Name = "Version",
		Text = "v" .. tostring(app and app.version or "1.0.0") .. "  //  " .. State.companion(),
		TextColor3 = Palette.text.dim,
		TextSize = 10,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 12),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		LayoutOrder = 1,
		Parent = footer,
	})

	Components.button({
		Name = "QuickMenuHint",
		Text = "quick menu: ;",
		Variant = "dark",
		Size = UDim2.new(1, 0, 0, 30),
		LayoutOrder = 2,
		Parent = footer,
		OnClick = function()
			if app and app.ToggleQuickMenu then
				app.ToggleQuickMenu()
			end
		end,
	})

	-- API ----------------------------------------------------------------------

	local sidebar = {
		frame = frame,
		providerDropdown = providerDropdown,
		keyInput = keyInput,
		modelInput = modelInput,
		sessions = sessions,
	}

	function sidebar:refreshSessions()
		Util.clear(sessions)

		local entries = State.data.sessions or {}

		local current = Components.button({
			Name = "Current",
			Text = "[current] " .. tostring(#State.history) .. " messages",
			Variant = "dark",
			Size = UDim2.new(1, 0, 0, 28),
			LayoutOrder = 0,
			Parent = sessions,
			TextXAlignment = Enum.TextXAlignment.Left,
			OnClick = function()
				if app and app.dashboard then
					app.dashboard:setTab("Chat")
				end
			end,
		})
		current.TextColor3 = Palette.neon.green

		if #entries == 0 then
			Fonts.new("TextLabel", "small", {
				Name = "Empty",
				Text = "No archived conversations yet.",
				TextColor3 = Palette.text.dim,
				AutomaticSize = Enum.AutomaticSize.Y,
				Size = UDim2.new(1, 0, 0, 0),
				TextWrapped = true,
				LayoutOrder = 1,
				Parent = sessions,
			})
			return
		end

		for index, session in ipairs(entries) do
			local row = Components.button({
				Name = "Session" .. tostring(index),
				Text = session.title or "Untitled",
				Variant = "dark",
				Size = UDim2.new(1, 0, 0, 28),
				LayoutOrder = index,
				Parent = sessions,
				TextXAlignment = Enum.TextXAlignment.Left,
				OnClick = function()
					State.setHistory(session.messages or {})
					if app and app.OnHistoryRestored then
						app.OnHistoryRestored()
					end
					sidebar:refreshSessions()
				end,
			})
			row.TextColor3 = Palette.text.secondary
		end
	end

	function sidebar:refresh()
		sidebar.providerDropdown:SetValue(State.provider())
		providerHint.Text = Providers.get(State.provider()).description
		keyInput.Text = State.apiKey(State.provider())
		keyInput.PlaceholderText = Providers.get(State.provider()).keyLabel
		modelInput.Text = State.model(Providers.get(State.provider()).model)
		transport.Text = "transport: " .. Http.transportName()
		transport.TextColor3 = Http.available() and Palette.text.dim or Palette.neon.pink

		for name, button in pairs(companionButtons) do
			local active = name == State.companion()
			button.BackgroundColor3 = active and Palette.surfaces.border or Palette.surfaces.card
			local stroke = button:FindFirstChildOfClass("UIStroke")
			if stroke then
				stroke.Color = active and Palette.character(name).glow or Palette.surfaces.border
			end
		end

		sidebar:refreshSessions()
	end

	sidebar:refresh()

	return sidebar
end

--- Re-applies state-driven visuals (used when the dashboard opens).
function Sidebar.refresh(app)
	if app and app.sidebar and app.sidebar.refresh then
		app.sidebar:refresh()
	end
end

return Sidebar
end

__modules["ui/Tutorial"] = function(require)
--[[
	ui/Tutorial.lua
	First-run onboarding from idea/main.md §4 and idea/ui-creation.md §5.

	  * choose rick.png or morty.png as the guide
	  * dialogue types out character-by-character at 0.03s with a click per glyph
	  * a custom vector arrow is drawn natively (rotated square head + shaft) and
	    bounced with math.sin(tick() * 5) * 10 beside the control being explained
	  * clicking the dialogue frame reveals the rest instantly

	Layout: the card splits into a portrait column (left) and a body column
	(right) that swaps between the dialogue label and the companion picker.
]]

local Assets = require("core/Assets")
local Companion = require("ui/Companion")
local Components = require("ui/Components")
local Fonts = require("core/Fonts")
local Palette = require("core/Palette")
local State = require("core/State")
local Typewriter = require("core/Typewriter")
local Util = require("core/Util")

local Tutorial = {}

Tutorial.DIM = 0.55

--- In-character script, one per guide.
Tutorial.dialogue = {
	Rick = {
		welcome = "Alright, listen up. This is the dashboard. Everything you'd normally do by hand, the AI does in about nine seconds. Try to keep up.",
		provider = "Pick your brain donor here. Every one of them already has its own payload template wired up. FreeBuff skips the whole API key song and dance if you're broke.",
		tabs = "Three modes. Chat to write and patch, Cowork to spawn the real interface outside this game, Code to run whatever you paste in. Try not to break the game.",
		quickmenu = "And whenever you're mid-game, hit the semicolon key. Type a prompt, it writes the script and runs it before you can even ask a follow-up question.",
		done = "That's it. Don't embarrass me.",
	},
	Morty = {
		welcome = "Oh jeez, okay, uh, this is the dashboard. It's, it's not that scary once you get used to it, I promise.",
		provider = "This dropdown picks which AI we, um, talk to. You can switch whenever, and each one already has its own request setup saved. You'll probably want FreeBuff if you don't have a key.",
		tabs = "Th-there's three tabs here. Chat is for talking, Cowork opens the big interface in your browser, and Code lets you run scripts right here.",
		quickmenu = "Oh! And, um, if you press the semicolon key you get a mini prompt box. You type what you want and it, it writes and runs the script for you.",
		done = "That's, that's everything! You're gonna do great, I mean, probably.",
	},
}

-- Pointer ---------------------------------------------------------------------

--- Native vector arrow: shaft plus a rotated square head (no external asset).
local function buildPointer(parent, companion)
	local theme = Palette.character(companion)

	local pointer = Util.create("Frame", {
		Name = "Pointer",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 34, 0, 18),
		AnchorPoint = Vector2.new(1, 0.5),
		Visible = false,
		ZIndex = 320,
		Parent = parent,
	})

	Util.create("Frame", {
		Name = "Shaft",
		BackgroundColor3 = theme.glow,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 22, 0, 3),
		Position = UDim2.new(0, 0, 0.5, 0),
		AnchorPoint = Vector2.new(0, 0.5),
		ZIndex = 320,
		Parent = pointer,
	}, { Util.corner(2) })

	local head = Util.create("Frame", {
		Name = "Head",
		BackgroundColor3 = theme.glow,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 11, 0, 11),
		Position = UDim2.new(1, -7, 0.5, 0),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Rotation = 45,
		ZIndex = 321,
		Parent = pointer,
	})
	Util.corner(2).Parent = head

	return pointer
end

--- Parks the pointer beside `getTarget()` and bounces it on a sine curve.
local function trackPointer(pointer, getTarget)
	local offset = 0

	local function update()
		local target = getTarget()
		if not target or not target.Parent then
			pointer.Visible = false
			return
		end

		local absolute = target.AbsolutePosition
		local size = target.AbsoluteSize

		pointer.Visible = target.Visible
		pointer.Position = UDim2.new(0, absolute.X - 12 + offset, 0, absolute.Y + size.Y / 2)
	end

	local connection = game:GetService("RunService").RenderStepped:Connect(function()
		offset = math.sin(tick() * 5) * 10 -- the bounce curve from the spec
		update()
	end)

	update()

	return function()
		if connection then
			connection:Disconnect()
			connection = nil
		end
		pointer.Visible = false
	end
end

-- Tutorial --------------------------------------------------------------------

--- `onFinish` runs once the user completes (or skips) onboarding.
function Tutorial.start(gui, app, onFinish)
	local overlay = Util.create("Frame", {
		Name = "Tutorial",
		BackgroundColor3 = Palette.overlay.color,
		BackgroundTransparency = Tutorial.DIM,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, 0),
		ZIndex = 300,
		Parent = gui,
	})

	local card = Components.panel({
		Name = "Guide",
		BackgroundColor3 = Palette.surfaces.background,
		Size = UDim2.new(0, 740, 0, 214),
		Position = UDim2.new(0.5, 0, 1, -40),
		AnchorPoint = Vector2.new(0.5, 1),
		ZIndex = 305,
		Parent = overlay,
	}, {
		Util.padding(16),
	})

	local portraitHolder = Util.create("Frame", {
		Name = "PortraitHolder",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 136, 1, 0),
		ZIndex = 306,
		Parent = card,
	})

	local textHolder = Util.create("Frame", {
		Name = "TextHolder",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -152, 1, -42),
		Position = UDim2.new(0, 152, 0, 0),
		ZIndex = 306,
		Parent = card,
	})

	local dialogue = Fonts.new("TextLabel", "body", {
		Name = "Dialogue",
		Text = "",
		RichText = true,
		TextColor3 = Palette.text.primary,
		TextSize = 14,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 1, 0),
		TextWrapped = true,
		TextYAlignment = Enum.TextYAlignment.Top,
		ZIndex = 307,
		Parent = textHolder,
	})

	local choiceHolder = Util.create("Frame", {
		Name = "Choices",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, 0),
		Visible = false,
		ZIndex = 307,
		Parent = textHolder,
	})

	local buttonRow = Util.create("Frame", {
		Name = "Buttons",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -152, 0, 30),
		Position = UDim2.new(0, 152, 1, -30),
		ZIndex = 307,
		Parent = card,
	}, {
		Util.list({
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 8),
			VerticalAlignment = Enum.VerticalAlignment.Center,
		}),
	})

	-- Fixed offset width: a scale-width child inside this horizontal
	-- UIListLayout would stretch and push the buttons off the card.
	local progress = Fonts.new("TextLabel", "small", {
		Name = "Progress",
		Text = "",
		TextColor3 = Palette.text.dim,
		TextSize = 10,
		BackgroundTransparency = 1,
		Size = UDim2.new(0, 220, 1, 0),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		LayoutOrder = 1,
		Parent = buttonRow,
	})

	local guidePortrait
	local pointer
	local stopTracking

	local function mountPortrait(companion)
		if guidePortrait then
			guidePortrait:Destroy()
		end

		guidePortrait = Companion.guide(portraitHolder, companion, {
			Size = Companion.GUIDE_SIZE,
			Position = UDim2.new(0, 0, 0.5, 0),
			AnchorPoint = Vector2.new(0, 0.5),
			Parent = portraitHolder,
		})

		if pointer then
			pointer:Destroy()
		end

		pointer = buildPointer(overlay, companion)
	end

	local function setTarget(getTarget)
		if stopTracking then
			stopTracking()
			stopTracking = nil
		end

		if getTarget then
			stopTracking = trackPointer(pointer, getTarget)
		elseif pointer then
			pointer.Visible = false
		end
	end

	-- Stop the RenderStepped loop if the overlay disappears mid-tour.
	overlay.Destroying:Connect(function()
		if stopTracking then
			stopTracking()
			stopTracking = nil
		end
	end)

	-- Steps -------------------------------------------------------------------

	local steps = {}
	local index = 1
	local handle
	local showStep
	local nextButton

	local function advance()
		if handle then
			handle.skip()
			handle = nil
		end

		local previous = steps[index]
		if previous and previous.onLeave then
			previous.onLeave()
		end

		index += 1
		showStep()
	end

	local function buildChoices()
		Util.clear(choiceHolder)

		Fonts.new("TextLabel", "body", {
			Name = "Prompt",
			Text = "Who's tagging along for the ride?",
			TextColor3 = Palette.text.primary,
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 22),
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 308,
			Parent = choiceHolder,
		})

		for index2, name in ipairs(Palette.characterOrder) do
			local theme = Palette.character(name)
			local offset = (index2 - 1) * 174

			local choice = Components.button({
				Name = name .. "Choice",
				Text = theme.label,
				Variant = "dark",
				Size = UDim2.new(0, 164, 0, 126),
				Position = UDim2.new(0, offset, 0, 32),
				ZIndex = 308,
				Parent = choiceHolder,
				TextColor3 = theme.text,
				OnClick = function()
					State.setCompanion(name)
					State.save()
					if app.OnCompanionChanged then
						app.OnCompanionChanged(name)
					end
					mountPortrait(name)
					advance()
				end,
			})

			choice.TextYAlignment = Enum.TextYAlignment.Bottom
			choice.TextSize = 13

			Util.create("ImageLabel", {
				Name = "Portrait",
				BackgroundTransparency = 1,
				Image = Assets.portrait(name),
				ScaleType = Enum.ScaleType.Fit,
				Size = UDim2.new(1, -16, 0, 84),
				Position = UDim2.new(0.5, 0, 0, 4),
				AnchorPoint = Vector2.new(0.5, 0),
				ZIndex = 309,
				Parent = choice,
			})
		end
	end

	local function speak(text)
		if handle then
			handle.skip()
		end

		handle = Typewriter.play(dialogue, text, {
			onComplete = function()
				nextButton.Text = index >= #steps and "Finish" or "Next"
			end,
		})
		Typewriter.bindSkip(card, handle)
	end

	showStep = function()
		local step = steps[index]
		if not step then
			Tutorial.finish(app, overlay, onFinish)
			return
		end

		if step.onEnter then
			step.onEnter()
		end

		if step.kind == "choose" then
			progress.Text = "choose your companion"
			dialogue.Visible = false
			choiceHolder.Visible = true
			nextButton.Visible = false
			setTarget(nil)
			buildChoices()
			return
		end

		progress.Text = string.format("step %d of %d", index, #steps)
		choiceHolder.Visible = false
		dialogue.Visible = true
		nextButton.Visible = true

		local lines = Tutorial.dialogue[State.companion()] or Tutorial.dialogue.Rick
		speak(lines[step.key] or "...")
		setTarget(step.target)
	end

	Components.button({
		Name = "Skip",
		Text = "Skip tour",
		Variant = "dark",
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 2,
		Parent = buttonRow,
		OnClick = function()
			Tutorial.finish(app, overlay, onFinish)
		end,
	})

	nextButton = Components.button({
		Name = "Next",
		Text = "Next",
		Variant = "green",
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 3,
		Parent = buttonRow,
		OnClick = advance,
	})

	-- Step list ---------------------------------------------------------------

	if not State.data.companion then
		table.insert(steps, { kind = "choose" })
	end

	table.insert(steps, {
		key = "welcome",
		onEnter = function()
			if app.dashboard then
				app.dashboard:setVisible(true)
				app.dashboard:setTab("Chat")
			end
		end,
	})

	table.insert(steps, {
		key = "provider",
		target = function()
			return app.sidebar and app.sidebar.providerDropdown.Toggle
		end,
	})

	table.insert(steps, {
		key = "tabs",
		onEnter = function()
			if app.dashboard then
				app.dashboard:setTab("Cowork")
			end
		end,
		target = function()
			return app.dashboard and app.dashboard.tabs
		end,
	})

	table.insert(steps, {
		key = "quickmenu",
		onEnter = function()
			if app.quickMenu then
				app.quickMenu:open()
			end
		end,
		onLeave = function()
			if app.quickMenu then
				app.quickMenu:close()
			end
		end,
		target = function()
			return app.quickMenu and app.quickMenu.module
		end,
	})

	table.insert(steps, { key = "done" })

	mountPortrait(State.companion())
	showStep()

	return overlay
end

--- Commits onboarding and tears the overlay down.
function Tutorial.finish(app, overlay, onFinish)
	State.data.onboarded = true
	State.data.companion = State.companion()
	State.save()

	if app.quickMenu and app.quickMenu.close then
		app.quickMenu:close()
	end

	if overlay then
		overlay:Destroy()
	end

	if onFinish then
		onFinish()
	end
end

return Tutorial
end

