    </style>
  </head>
  <body>
    <header>
      <span class="brand">Cowork Bridge</span>
      <span class="badge" id="provider-badge">connecting...</span>
      <span class="badge" id="companion-badge">&nbsp;</span>
      <span class="grow"></span>
      <span class="status" id="status">idle</span>
    </header>

    <main>
      <aside>
        <h2>Conversations</h2>
        <button id="new-chat">+ New conversation</button>
        <div id="sessions"></div>
        <h2 style="margin-top: 10px">Agent loop</h2>
        <button id="agent-mode">Plan &rarr; implement</button>
        <p class="hint" style="margin: 0">
          Multi-step mode plans first, then writes the Luau in a second pass.
        </p>
      </aside>

      <section id="chat">
        <div id="transcript"></div>
        <div class="composer">
          <div class="row">
            <textarea id="prompt" rows="1" placeholder="Ask for a Luau script, a patch, or an explanation..."></textarea>
            <button class="primary" id="send">Send</button>
          </div>
          <div class="hint">
            Enter to send &middot; Shift+Enter for a new line &middot; click any code block to copy it
          </div>
        </div>
      </section>
    </main>

    <script>
      const transcript = document.getElementById('transcript');
      const promptBox = document.getElementById('prompt');
      const sendButton = document.getElementById('send');
      const statusEl = document.getElementById('status');
      const providerBadge = document.getElementById('provider-badge');
      const companionBadge = document.getElementById('companion-badge');
      const sessionsEl = document.getElementById('sessions');
      const newChatButton = document.getElementById('new-chat');
      const agentButton = document.getElementById('agent-mode');

      let messages = [];
      let sessions = [];
      let agentMode = false;
      let busy = false;

      function escapeHtml(text) {
        return text
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;');
      }

      // Renders fenced code blocks and inline code without any dependency.
      function render(text) {
        const parts = [];
        const pattern = /```([\w+-]*)\r?\n([\s\S]*?)```/g;
        let cursor = 0;
        let match;

        while ((match = pattern.exec(text)) !== null) {
          if (match.index > cursor) {
            parts.push({ type: 'text', value: text.slice(cursor, match.index) });
          }
          parts.push({ type: 'code', lang: match[1] || 'lua', value: match[2] });
          cursor = match.index + match[0].length;
        }

        if (cursor < text.length) parts.push({ type: 'text', value: text.slice(cursor) });

        return parts
          .map((part) => {
            if (part.type === 'code') {
              return (
                '<div class="code-head">' +
                escapeHtml(part.lang) +
                ' &middot; click to copy</div>' +
                '<pre data-code="1">' +
                escapeHtml(part.value.replace(/\s+$/, '')) +
                '</pre>'
              );
            }
            const escaped = escapeHtml(part.value).replace(/`([^`\n]+)`/g, '<code class="inline">$1</code>');
            return escaped;
          })
          .join('');
      }

      function addTurn(role, text) {
        const turn = document.createElement('div');
        turn.className = 'turn ' + role;
        turn.innerHTML =
          '<div class="who">' +
          (role === 'user' ? 'YOU' : 'AI') +
          '</div>' +
          '<div class="body"><div class="name">' +
          (role === 'user' ? 'Operator' : 'Companion') +
          '</div><div class="bubble">' +
          render(text) +
          '</div></div>';
        transcript.appendChild(turn);
        transcript.scrollTop = transcript.scrollHeight;
      }

      function setStatus(text, kind) {
        statusEl.textContent = text;
        statusEl.className = 'status' + (kind ? ' ' + kind : '');
      }

      function setBusy(value) {
        busy = value;
        sendButton.disabled = value;
        sendButton.textContent = value ? 'Working...' : 'Send';
      }

      function renderSessions() {
        sessionsEl.innerHTML = '';
        sessions.forEach((session, index) => {
          const node = document.createElement('div');
          node.className = 'session' + (session.active ? ' active' : '');
          node.textContent = session.title;
          node.addEventListener('click', () => {
            sessions.forEach((item) => (item.active = false));
            session.active = true;
            messages = session.messages.slice();
            transcript.innerHTML = '';
            for (const message of messages) addTurn(message.role, message.content);
            renderSessions();
          });
          sessionsEl.appendChild(node);
          if (index === 0 && !session.active) session.active = true;
        });
      }

      function currentSession() {
        if (sessions.length === 0) {
          sessions.push({ title: 'New conversation', messages: [], active: true });
        }
        return sessions[0];
      }

      async function send() {
        const content = promptBox.value.trim();
        if (!content || busy) return;

        promptBox.value = '';
        addTurn('user', content);
        messages.push({ role: 'user', content });

        const session = currentSession();
        session.messages = messages.slice();
        if (session.title === 'New conversation') {
          session.title = content.slice(0, 40);
          renderSessions();
        }

        setBusy(true);
        setStatus(agentMode ? 'agent loop running...' : 'waiting for provider...');

        try {
          const response = await fetch(agentMode ? '/api/agent' : '/api/chat', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ messages }),
          });

          const data = await response.json();
          if (data.error) throw new Error(data.error);

          addTurn('assistant', data.text);
          messages.push({ role: 'assistant', content: data.text });
          session.messages = messages.slice();
          setStatus('replied in ' + data.ms + 'ms', 'ok');
        } catch (error) {
          addTurn('assistant', '**Bridge error**\n\n' + String(error.message || error));
          setStatus('request failed', 'error');
        } finally {
          setBusy(false);
        }
      }

      sendButton.addEventListener('click', send);

      promptBox.addEventListener('keydown', (event) => {
        if (event.key === 'Enter' && !event.shiftKey) {
          event.preventDefault();
          send();
        }
      });

      promptBox.addEventListener('input', () => {
        promptBox.style.height = 'auto';
        promptBox.style.height = Math.min(promptBox.scrollHeight, 220) + 'px';
      });

      transcript.addEventListener('click', (event) => {
        const pre = event.target.closest('pre');
        if (!pre) return;
        navigator.clipboard.writeText(pre.textContent).then(() => {
          setStatus('code copied', 'ok');
        });
      });

      newChatButton.addEventListener('click', () => {
        if (messages.length > 0) {
          sessions[0].messages = messages.slice();
          if (sessions[0].title === 'New conversation') {
            sessions[0].title = (messages[0] && messages[0].content.slice(0, 40)) || 'Conversation';
          }
        }
        sessions.forEach((item) => (item.active = false));
        sessions.unshift({ title: 'New conversation', messages: [], active: true });
        messages = [];
        transcript.innerHTML = '';
        renderSessions();
        setStatus('new conversation', 'ok');
      });

      agentButton.addEventListener('click', () => {
        agentMode = !agentMode;
        agentButton.textContent = agentMode ? 'Agent loop: ON' : 'Plan \u2192 implement';
        agentButton.classList.toggle('primary', agentMode);
        setStatus(agentMode ? 'multi-step loop enabled' : 'single-shot mode', 'ok');
      });

      (async function boot() {
        try {
          const response = await fetch('/api/status');
          const data = await response.json();
          providerBadge.textContent = data.provider + ' - ' + data.model;
          providerBadge.classList.add('live');
          companionBadge.textContent = 'companion: ' + data.companion;
          if (!data.hasKey && data.provider !== 'AgentRouter') {
            setStatus('no API key configured', 'error');
          } else {
            setStatus('ready', 'ok');
          }
        } catch (error) {
          providerBadge.textContent = 'bridge offline';
          setStatus('cannot reach bridge', 'error');
        }

        addTurn(
          'assistant',
          '**Cowork bridge online.**\n\nThis window talks straight to your configured provider, so nothing is blocked by the Roblox HTTP whitelist.\n\nAsk for a Luau script and I will return it in a code block you can copy into the executor.'
        );
        renderSessions();
        promptBox.focus();
      })();
    </script>
  </body>
</html>
]=],
	["bridge/launch_bridge.bat"] = [=[
